INSERT INTO `statuses` (`id`, `name`, `active`, `prepareBy`, `created_at`, `updated_at`) VALUES (1,'Hoạt động',1,'Admin','2026-08-28 21:05:59','2026-08-28 21:05:59'),(2,'Ngừng hoạt động',1,'Admin','2026-08-28 21:05:59','2026-09-01 09:16:46'),(3,'Chờ duyệt',1,'Admin','2026-08-28 21:05:59','2026-08-28 21:05:59'),(4,'Từ chối',1,'Admin','2026-08-28 21:05:59','2026-09-01 09:16:49'),(5,'Hết hạn',1,'Admin','2026-08-28 21:05:59','2026-09-01 09:16:42');
INSERT INTO `permission_groups` (`id`, `name`, `sort_order`, `created_at`, `updated_at`) VALUES (1,'Dữ Liệu Gốc',1,'2026-08-30 20:51:18','2026-08-30 20:51:18'),(2,'Danh Mục',2,'2026-08-30 20:51:18','2026-08-30 20:51:18'),(3,'Nhập',3,'2026-08-30 20:51:18','2026-08-30 20:51:18'),(4,'Sử Dụng',4,'2026-08-30 20:51:18','2026-08-30 20:51:18'),(5,'Tồn Kho',5,'2026-08-30 20:51:18','2026-08-30 20:51:18'),(6,'Dự Trù',6,'2026-08-30 20:51:18','2026-08-30 20:51:18'),(7,'Đánh Giá Hạn Dùng',7,'2026-08-30 20:51:18','2026-08-30 20:51:18'),(8,'Quản Trị',8,'2026-08-30 20:51:18','2026-08-30 20:51:18');
INSERT INTO `permissions` (`id`, `permission_group`, `parent_id`, `name`, `display_name`, `description`, `created_at`, `updated_at`) VALUES (5,2,NULL,'category_material_view','Xem Danh Mục Vật Tư Chung','Thấy mục Danh Mục › Vật Tư trên menu và mở màn hình.\nLưu ý: từng tab bên trong (Danh mục vật tư công ty, Vật tư của phòng, 3 tab danh sách theo chu kỳ) cần thêm quyền xem tab tương ứng.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(6,2,NULL,'category_material_create','Thêm Danh Mục Vật Tư Chung','Thêm mã vật tư mới vào Danh mục vật tư công ty: chọn tên vật tư và nhà sản xuất, khai thông tin kỹ thuật, Part Number, 4 tiêu chí phân loại, bộ phận mua hàng, thời gian đặt hàng.\nLưu ý: mã M00001... tự sinh. Mã mới ở trạng thái Chờ duyệt, các phòng chỉ dùng được sau khi được duyệt.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(7,2,NULL,'category_material_update','Sửa Danh Mục Vật Tư Chung','Sửa thông tin mã vật tư trong Danh mục vật tư công ty (nút Sửa trên dòng). Mỗi lần sửa được lưu vào lịch sử thay đổi của mã.\nLưu ý: sửa xong mã quay về Chờ duyệt và phải được duyệt lại. Thời gian đặt hàng không sửa ở đây mà dùng quyền Điều Chỉnh Thời Gian Đặt Hàng.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(8,2,NULL,'category_material_deActive','Vô Hiệu Danh Mục Vật Tư Chung','Khoá hoặc mở khoá mã vật tư trong Danh mục vật tư công ty (bắt buộc ghi lý do). Mã bị khoá không còn xuất hiện khi chọn vật tư ở các màn nghiệp vụ.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(9,2,NULL,'category_chemical_view','Xem Danh Mục Hoá Chất','Thấy mục Danh Mục › Hoá Chất trên menu và mở màn hình.\nLưu ý: từng tab bên trong (Danh mục hoá chất công ty, Hoá chất của phòng, Danh sách hoá chất theo sản phẩm) cần thêm quyền xem tab tương ứng.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(10,2,NULL,'category_chemical_create','Thêm Danh Mục Hoá Chất','Thêm mã hoá chất mới vào Danh mục hoá chất công ty: chọn tên hoá chất và nhà sản xuất, khai loại, tỉ trọng, điều kiện bảo quản, hạn dùng mặc định, thời gian đặt hàng.\nLưu ý: mã mới ở trạng thái Chờ duyệt. Phân loại NĐ 24/2026 tự suy từ hoạt chất thành phần, không khai tay.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(11,2,NULL,'category_chemical_update','Sửa Danh Mục Hoá Chất','Sửa thông tin mã hoá chất trong Danh mục hoá chất công ty (mỗi lần sửa lưu lịch sử), và xác nhận \"Đã khai báo Cổng thông tin quốc gia\" cho mã hoá chất (nhập lại mật khẩu).\nLưu ý: sửa thông tin xong mã quay về Chờ duyệt. Xác nhận khai báo Cổng chỉ làm một lần, không gỡ lại được và không làm mã phải duyệt lại.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(12,2,NULL,'category_chemical_deActive','Vô Hiệu Danh Mục Hoá Chất','Khoá hoặc mở khoá mã hoá chất trong Danh mục hoá chất công ty (bắt buộc ghi lý do). Mã bị khoá không còn xuất hiện khi chọn hoá chất ở các màn nghiệp vụ.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(13,2,NULL,'category_standard_view','Xem Danh Mục Chất Chuẩn Chung','Thấy mục Danh Mục › Chất Chuẩn trên menu và mở màn hình.\nLưu ý: từng tab bên trong (Danh mục chất chuẩn công ty, Chất chuẩn của phòng, Danh sách chất chuẩn theo sản phẩm) cần thêm quyền xem tab tương ứng.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(14,2,NULL,'category_standard_create','Thêm Danh Mục Chất Chuẩn Chung','Thêm mã chất chuẩn mới vào Danh mục chất chuẩn công ty: chọn tên chuẩn và nguồn gốc / nhà sản xuất, khai số CAS, phân nhóm chuẩn (Chuẩn Chính, Chuẩn Tạp, Chuẩn Thứ Cấp...), tỷ trọng, hạn dùng mặc định, điều kiện bảo quản, thời gian đặt hàng.\nLưu ý: mã mới ở trạng thái Chờ duyệt. Chuẩn chưa có phân nhóm thì không nhập kho được.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(15,2,NULL,'category_standard_update','Sửa Danh Mục Chất Chuẩn Chung','Sửa thông tin mã chất chuẩn trong Danh mục chất chuẩn công ty (nút Sửa trên dòng). Mỗi lần sửa được lưu vào lịch sử thay đổi.\nLưu ý: sửa xong mã quay về Chờ duyệt và phải được duyệt lại. Thời gian đặt hàng dùng quyền Điều Chỉnh Thời Gian Đặt Hàng.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(16,2,NULL,'category_standard_deActive','Vô Hiệu Danh Mục Chất Chuẩn Chung','Khoá hoặc mở khoá mã chất chuẩn trong Danh mục chất chuẩn công ty (bắt buộc ghi lý do). Mã bị khoá không còn xuất hiện khi chọn chất chuẩn ở các màn nghiệp vụ.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(17,3,NULL,'import_material_view','Xem Phiếu Nhập Vật Tư','Thấy mục Nhập › Vật Tư trên menu và mở màn hình.\nLưu ý: tab Sổ nhập vật tư và Chờ kiểm tra cần thêm quyền xem tab tương ứng.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(18,3,NULL,'import_material_create','Thêm Phiếu Nhập Vật Tư','Lập phiếu nhập kho vật tư cho phòng đang chọn: chọn vật tư của phòng, số lượng, số lần nhập (mỗi lô một mã xuất nhập, tối đa 50), thông tin chứng từ, định khu tạm trong khu Biệt Trữ, file đính kèm.\nLưu ý: lô mới ở trạng thái Chờ kiểm tra, chưa cộng vào tồn cho tới khi kiểm tra Đạt.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(19,3,NULL,'import_material_update','Sửa Phiếu Nhập Vật Tư','Điều chỉnh thông tin phiếu nhập vật tư (mỗi lần sửa lưu lịch sử) và Xác nhận kiểm tra lô ở tab Chờ kiểm tra: Đạt thì lô vào tồn và chuyển về định khu thật; Không đạt thì trả hàng, lô không vào tồn.\nLưu ý: kết quả kiểm tra là quyết định cuối, không kiểm tra lại được.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(21,3,NULL,'import_chemical_view','Xem Phiếu Nhập Hoá Chất','Thấy mục Nhập › Hoá Chất trên menu và mở màn hình.\nLưu ý: tab Nhập hoá chất, Sổ nhập hoá chất, Báo cáo nhập hoá chất cần thêm quyền xem tab tương ứng.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(22,3,NULL,'import_chemical_create','Thêm Phiếu Nhập Hoá Chất','Lập phiếu nhập kho hoá chất cho phòng đang chọn: chọn hoá chất của phòng, số lượng, số lần nhập (mỗi lô một mã, tối đa 50), số lô, nhà cung cấp, hạn sử dụng, số / ngày hoá đơn, định khu tạm trong khu Biệt Trữ, file đính kèm.\nLưu ý: hoá chất thuộc diện ngưỡng PL IV được báo trước tồn trữ toàn công ty sau khi nhập. Lô mới ở trạng thái Chờ kiểm tra, chưa vào tồn.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(23,3,NULL,'import_chemical_update','Sửa Phiếu Nhập Hoá Chất','Điều chỉnh thông tin phiếu nhập hoá chất (mỗi lần sửa lưu lịch sử) và Xác nhận kiểm tra lô đang chờ ở tab Nhập hoá chất: Đạt thì lô vào tồn và chuyển về định khu thật; Không đạt thì trả hàng.\nLưu ý: lô chưa kiểm tra chỉ đặt được trong khu Biệt Trữ.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(25,3,NULL,'import_standard_view','Xem Phiếu Nhập Chất Chuẩn','Thấy mục Nhập › Chất Chuẩn trên menu và mở màn hình.\nLưu ý: tab Nhập chất chuẩn và Sổ nhập chất chuẩn cần thêm quyền xem tab tương ứng.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(26,3,NULL,'import_standard_create','Thêm Phiếu Nhập Chất Chuẩn','Nhập ống chuẩn cho phòng đang chọn: chọn chất chuẩn của phòng, lượng / ống, số lần nhập (mỗi ống một mã ống chuẩn, tối đa 50), thông tin lô, loại hạn dùng, chỉ tiêu kiểm, CoA đính kèm.\nLưu ý: ống mới ở trạng thái Chờ kiểm tra trong khu Biệt Trữ, chưa vào tồn.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(27,3,NULL,'import_standard_update','Sửa Phiếu Nhập Chất Chuẩn','Điều chỉnh thông tin phiếu nhập ống chuẩn (mỗi lần sửa lưu lịch sử) và Xác nhận kiểm tra ống đang chờ ở tab Nhập chất chuẩn: Đạt thì ống vào tồn và chuyển về định khu thật.\nLưu ý: sổ nhập chất chuẩn không khoá phiếu; ống hỏng đưa qua Cách ly ở Tồn Kho Chất Chuẩn.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(29,4,NULL,'export_material_view','Xem Cấp Phát Vật Tư','Thấy mục Đề Nghị - Sử Dụng › Vật Tư trên menu và mở màn hình; đồng thời thấy Thống Kê › Vật Tư (lượng vật tư đã cấp theo từng đối tượng).\nLưu ý: từng tab bên trong cần thêm quyền xem tab tương ứng.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(30,4,NULL,'export_material_request','Đề Nghị Cấp Phát Vật Tư','Lập, sửa và gửi đề nghị cấp phát vật tư: đề nghị nội bộ (Thường quy, Theo ĐG rủi ro), đề nghị liên phòng ban xin vật tư từ phòng khác và đề nghị VPP đến Hành Chánh; sửa và gửi lại phiếu đang Lưu tạm hoặc Bị từ chối.\nLưu ý: gồm cả gửi đề nghị VPP từ danh sách vật tư cần đề nghị Hành Chính. Đề nghị nội bộ gửi đi sẽ qua các bước ký theo Trình Ký Đề Nghị CP Vật Tư.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(31,4,NULL,'export_material_approve','Duyệt Cấp Phát Vật Tư','Ký đồng ý hoặc từ chối đề nghị cấp phát vật tư nội bộ khi tới bước ký của mình (nhập lại mật khẩu). Nút ký nằm trong chi tiết phiếu; đề nghị chờ ký hiện ở Trang chủ.\nLưu ý: chỉ có quyền là chưa đủ, người ký từng bước được xác định theo Dữ Liệu Gốc › Trình Ký Đề Nghị CP Vật Tư (vai trò, cấp ký, điều kiện).','2026-08-30 20:51:18','2026-11-03 11:35:42'),(32,4,NULL,'export_material_issue','Xuất Kho Vật Tư','Cấp phát (xuất kho) các dòng đề nghị đã duyệt ở tab Chờ cấp phát: kiểm tra lô và số lượng gợi ý theo FEFO/FIFO rồi bấm Cấp Phát để trừ tồn và tự ghi Sổ cấp phát. Gồm cả gửi / huỷ Đề nghị hiệu chuẩn với vật tư cần hiệu chuẩn trước khi dùng.\nLưu ý: đổi lô hoặc đổi số lượng khác đề xuất cần thêm quyền Điều Chỉnh Mã Xuất Nhập / Điều Chỉnh Số Lượng Khi Cấp Phát Vật Tư.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(33,4,NULL,'export_chemical_view','Xem Cấp Phát Hoá Chất','Thấy mục Đề Nghị - Sử Dụng › Hoá Chất trên menu và mở màn hình.\nLưu ý: từng tab bên trong cần thêm quyền xem tab tương ứng.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(34,4,NULL,'export_chemical_request','Tạo Đề Nghị Chuyển Hoá Chất Liên Phòng Ban','Lập đề nghị xin hoá chất từ kho của phòng khác (chọn phòng được đề nghị, hoá chất, số lượng, ngày mong muốn), sửa hoặc huỷ đề nghị khi còn ở trạng thái lưu.\nLưu ý: đề nghị chuyển hoá chất liên phòng ban không có bước ký duyệt.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(36,4,NULL,'export_chemical_issue','Xuất Kho Hoá Chất','Ghi phiếu Sử dụng hoá chất ở tab Sử Dụng Hoá Chất (quét mã, chọn từ tồn kho hoặc theo gói sản phẩm - chỉ tiêu): lưu là trừ tồn ngay, không cần ký duyệt.\nLưu ý: dùng hoá chất cấm bắt buộc chọn Người Kiểm Tra là người có vai trò Quản Lý Kho Hoá Chất của phòng.\nLưu ý: sửa hoặc khoá dòng đã ghi ở Sổ sử dụng hoá chất cần quyền Điều Chỉnh Sổ Sử Dụng Hoá Chất.','2026-08-30 20:51:18','2026-11-03 12:44:54'),(37,4,NULL,'export_standard_view','Xem Cấp Phát Chất Chuẩn','Thấy mục Đề Nghị - Sử Dụng › Chất Chuẩn trên menu và mở màn hình.\nLưu ý: từng tab bên trong cần thêm quyền xem tab tương ứng.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(38,4,NULL,'export_standard_request','Đề Nghị Cấp Phát Chất Chuẩn','Lập, sửa và gửi đề nghị cấp phát chuẩn nội bộ (tổ xin ống chuẩn từ kho của phòng) và đề nghị cấp phát chuẩn liên phòng ban (xin từ kho của phòng khác).\nLưu ý: đề nghị chất chuẩn không có bước ký duyệt. Người trong tổ chỉ thấy và dùng được ống đã cấp cho tổ mình.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(40,4,NULL,'export_standard_issue','Xuất Kho Chất Chuẩn','Kho cấp phát ống chuẩn cho tổ theo đề nghị nội bộ; cấp phát (hoặc từ chối) đề nghị liên phòng ban do phòng khác gửi tới; ghi phiếu Sử dụng cho ống đã cấp ở tab Sử dụng chuẩn.\nLưu ý: cấp phát trừ tồn của phòng ngay khi lưu.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(41,5,NULL,'inventory_material_view','Xem Tồn Kho Vật Tư','Thấy mục Tồn Kho › Vật Tư trên menu và xem tồn của phòng đang chọn. Tồn tính tự động từ nhập, cân đối, cấp phát; không có chỗ nhập tồn bằng tay.\nLưu ý: từng tab bên trong cần thêm quyền xem tab tương ứng.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(42,5,NULL,'inventory_chemical_view','Xem Tồn Kho Hoá Chất','Thấy mục Tồn Kho › Hoá Chất trên menu và xem tồn của phòng đang chọn theo kỳ (tồn đầu kỳ, nhập, cân đối, sử dụng, huỷ, tồn cuối kỳ). Tồn tính tự động, không nhập tay.\nLưu ý: từng tab bên trong cần thêm quyền xem tab tương ứng.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(43,5,NULL,'inventory_standard_view','Xem Tồn Kho Chất Chuẩn','Thấy mục Tồn Kho › Chất Chuẩn trên menu và xem tồn ống chuẩn của phòng đang chọn theo kỳ. Tồn tính tự động, không nhập tay.\nLưu ý: từng tab bên trong (kể cả Đánh giá hạn dùng CTC, Kế hoạch đánh giá) cần thêm quyền xem tab tương ứng.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(45,6,NULL,'estimate_material_view','Xem Dự Trù Vật Tư','Thấy mục Dự Trù › Vật Tư trên menu và mở màn hình (phiếu dự trù đề nghị bộ phận mua hàng mua vật tư).\nLưu ý: từng tab bên trong cần thêm quyền xem tab tương ứng.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(46,6,NULL,'estimate_material_create','Lập Dự Trù Vật Tư','Lập phiếu dự trù vật tư mới (chọn tháng / năm dự trù, ghi chú), kể cả lập nhanh bằng cách tick chọn ở Danh sách vật tư cần dự trù. Phiếu mới ở trạng thái Nháp.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(47,6,NULL,'estimate_material_update','Sửa Dự Trù Vật Tư','Sửa phiếu dự trù vật tư đang Nháp hoặc Bị từ chối: đổi tháng, ghi chú, thêm / sửa / bỏ mặt hàng, số lượng từng tháng, file đính kèm; rồi bấm Trình ký để gửi đi ký duyệt.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(48,6,NULL,'estimate_material_sign','Ký Duyệt Dự Trù Vật Tư','Ký đồng ý hoặc từ chối phiếu dự trù vật tư khi tới bước của mình (nhập lại mật khẩu). Bước 1: Quản Lý Bộ Phận của phòng lập phiếu; bước 2: Ban Giám Đốc.\nLưu ý: người ký còn được xác định theo vai trò và phạm vi phòng ban, không chỉ dựa vào quyền này. Phiếu chờ ký hiện ở Trang chủ.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(49,6,NULL,'estimate_chemical_view','Xem Dự Trù Hoá Chất','Thấy mục Dự Trù › Hoá Chất trên menu và mở màn hình (phiếu dự trù đề nghị Cung Ứng mua hoá chất).\nLưu ý: từng tab bên trong cần thêm quyền xem tab tương ứng.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(50,6,NULL,'estimate_chemical_create','Lập Dự Trù Hoá Chất','Lập phiếu dự trù hoá chất mới (chọn tháng / năm dự trù, ghi chú). Phiếu mới ở trạng thái Nháp.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(51,6,NULL,'estimate_chemical_update','Sửa Dự Trù Hoá Chất','Sửa phiếu dự trù hoá chất đang Nháp hoặc Bị từ chối: đổi tháng, ghi chú, thêm / sửa / bỏ mặt hàng, số lượng từng tháng, file đính kèm; rồi bấm Trình ký để gửi đi ký duyệt.\nLưu ý: hoá chất thuộc diện ngưỡng PL IV được báo trước tồn trữ toàn công ty sau khi mua; hoá chất đang nằm trong phiếu dự trù chưa xong thì không thêm lại được.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(52,6,NULL,'estimate_chemical_sign','Ký Duyệt Dự Trù Hoá Chất','Ký đồng ý hoặc từ chối phiếu dự trù hoá chất khi tới bước của mình (nhập lại mật khẩu). Bước 1: Quản Lý Bộ Phận của phòng lập phiếu; bước 2: Ban Giám Đốc.\nLưu ý: người ký còn được xác định theo vai trò và phạm vi phòng ban, không chỉ dựa vào quyền này. Phiếu chờ ký hiện ở Trang chủ.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(53,6,NULL,'estimate_standard_view','Xem Dự Trù Chất Chuẩn','Thấy mục Dự Trù › Chất Chuẩn trên menu và mở màn hình (phiếu dự trù đề nghị Cung Ứng mua chất chuẩn).\nLưu ý: từng tab bên trong cần thêm quyền xem tab tương ứng.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(54,6,NULL,'estimate_standard_create','Lập Dự Trù Chất Chuẩn','Lập phiếu dự trù chất chuẩn mới (chọn tháng / năm dự trù, ghi chú). Phiếu mới ở trạng thái Nháp.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(55,6,NULL,'estimate_standard_update','Sửa Dự Trù Chất Chuẩn','Sửa phiếu dự trù chất chuẩn đang Nháp hoặc Bị từ chối: đổi tháng, ghi chú, thêm / sửa / bỏ mặt hàng, số lượng từng tháng, file đính kèm; rồi bấm Trình ký để gửi đi ký duyệt.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(56,6,NULL,'estimate_standard_sign','Ký Duyệt Dự Trù Chất Chuẩn','Ký đồng ý hoặc từ chối phiếu dự trù chất chuẩn khi tới bước của mình (nhập lại mật khẩu). Bước 1: Quản Lý Bộ Phận của phòng lập phiếu; bước 2: Ban Giám Đốc.\nLưu ý: người ký còn được xác định theo vai trò và phạm vi phòng ban, không chỉ dựa vào quyền này. Phiếu chờ ký hiện ở Trang chủ.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(57,5,43,'stability_standard_view','Tab Đánh giá hạn dùng CTC','Xem tab Đánh giá hạn dùng CTC ở Tồn Kho › Chất Chuẩn: các phiếu theo dõi độ ổn định của ống chuẩn thứ cấp qua từng mốc (T0, T3, T6...) và trang chi tiết của từng phiếu.','2026-08-30 20:51:18','2026-11-10 17:37:47'),(58,5,NULL,'stability_standard_create','Thêm Đánh Giá Chuẩn Thứ Cấp','Lập phiếu đánh giá hạn dùng cho ống chuẩn thứ cấp (chọn ống, ngày bắt đầu, chu kỳ, các mốc và chỉ tiêu cần thử) và thêm mốc đánh giá vào phiếu đang chạy.\nLưu ý: chỉ ống CTC được tick Lô đánh giá hạn dùng lúc nhập mới lập phiếu được; mỗi ống chỉ có một phiếu còn hiệu lực.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(59,5,NULL,'stability_standard_update','Sửa Đánh Giá Chuẩn Thứ Cấp','Sửa phiếu đánh giá hạn dùng CTC và các mốc chưa có kết quả; cho phiếu đang Dừng đánh giá chạy tiếp.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(60,5,43,'stability_plan_view','Tab Kế hoạch đánh giá','Xem tab Kế hoạch đánh giá ở Tồn Kho › Chất Chuẩn: mọi mốc đánh giá của các phiếu còn hiệu lực xếp theo ngày đến hạn (quá hạn, sắp đến hạn, chưa tới hạn). Chỉ để xem.','2026-08-30 20:51:18','2026-11-10 17:37:47'),(63,8,NULL,'user_view','Xem Danh Sách User','Thấy mục Phân Quyền › User trên menu và xem danh sách tài khoản người dùng cùng phòng ban, tổ, nhóm quyền của từng người.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(64,8,NULL,'user_create','Thêm User','Tạo tài khoản người dùng mới: tên đăng nhập (không trùng toàn hệ thống), mật khẩu tạm, phòng ban, tổ, nhóm quyền.\nLưu ý: người dùng bị buộc đổi mật khẩu ở lần đăng nhập đầu tiên.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(65,8,NULL,'user_update','Sửa User','Sửa thông tin tài khoản: họ tên, phòng ban, tổ, các nhóm quyền và phạm vi phòng ban của từng nhóm quyền.\nLưu ý: nhập mật khẩu mới trong hộp thoại Sửa thì được xử lý như reset (mở khoá, buộc đổi ở lần đăng nhập sau).','2026-08-30 20:51:18','2026-11-03 11:35:42'),(66,8,NULL,'user_deActive','Vô Hiệu User','Vô hiệu hoá tài khoản khi nhân viên nghỉ việc, chuyển công tác: tài khoản không đăng nhập được nữa nhưng không bị xoá, tên trên phiếu cũ, chữ ký và nhật ký vẫn giữ nguyên.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(67,8,NULL,'role_view','Xem Nhóm Quyền','Thấy mục Phân Quyền › Nhóm Quyền trên menu và xem bảng phân quyền: mỗi nhóm quyền đang được tick những quyền nào. Chỉ xem.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(68,8,NULL,'role_update','Phân Quyền Cho Nhóm','Tick hoặc bỏ tick quyền cho các nhóm quyền trên bảng Nhóm Quyền. Thay đổi có hiệu lực ngay với mọi người thuộc nhóm.\nLưu ý: tick quyền con thì quyền cha được tick theo, bỏ quyền cha thì các quyền con bị bỏ theo. Không gỡ được quyền của nhóm Admin.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(69,8,NULL,'permission_view','Xem Danh Sách Quyền','Thấy mục Phân Quyền › Quyền trên menu và xem danh sách mọi quyền của hệ thống kèm diễn giải (màn hình này).','2026-08-30 20:51:18','2026-11-03 11:35:42'),(70,8,NULL,'userPermission_manage','Cấp Quyền Riêng Cho User','Cấp quyền riêng cho từng người ngoài nhóm quyền (nút Quyền Riêng ở màn User): với mỗi quyền chọn Theo nhóm quyền, Cho phép hoặc Từ chối.\nLưu ý: Từ chối chặn quyền đó dù nhóm quyền của người dùng có cấp.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(71,8,NULL,'auditTrail_view','Xem Audit Trail','Thấy mục Lịch Sử Đăng Nhập › Audit Trail và xem nhật ký hệ thống tự ghi: đăng nhập / đăng xuất, khoá tài khoản, đổi mật khẩu, ký duyệt, thêm - sửa - duyệt dữ liệu... kèm giá trị cũ và mới.\nLưu ý: nhật ký chỉ ghi thêm, không ai sửa hay xoá được, kể cả quản trị viên.','2026-08-30 20:51:18','2026-11-03 11:35:42'),(74,2,NULL,'category_material_approve','Duyệt Danh Mục Vật Tư Chung','Duyệt mã vật tư đang Chờ duyệt trong Danh mục vật tư công ty (nhập lại mật khẩu khi duyệt). Mã chờ duyệt hiện ở Trang chủ của người có quyền này.\nLưu ý: chỉ mã Đã duyệt mới được các phòng khai vào Vật tư của phòng và dùng ở Nhập, Đề nghị, Dự trù.','2026-09-02 19:06:20','2026-11-03 11:35:42'),(76,2,NULL,'category_material_dept_manage','Quản lý danh mục vật tư phòng','Thêm, sửa, khoá vật tư ở tab Vật tư của phòng (phòng đang chọn): đơn vị tính của phòng, phân loại của phòng, ngưỡng tồn tối thiểu / tối đa, định khu dự kiến.\nLưu ý: chỉ vật tư đã khai ở tab này mới nhập kho và đề nghị nội bộ được ở phòng. Tồn dưới ngưỡng tối thiểu thì vật tư tự vào Danh sách cần dự trù.','2026-09-02 19:06:20','2026-11-03 11:35:42'),(77,2,NULL,'category_chemical_approve','Duyệt Danh Mục Hoá Chất','Duyệt mã hoá chất đang Chờ duyệt trong Danh mục hoá chất công ty (nhập lại mật khẩu khi duyệt). Mã chờ duyệt hiện ở Trang chủ của người có quyền này.\nLưu ý: chỉ mã Đã duyệt mới được các phòng khai vào Hoá chất của phòng và dùng ở Nhập, Sử dụng, Dự trù.','2026-09-02 19:06:20','2026-11-03 11:35:42'),(79,2,NULL,'category_chemical_dept_manage','Quản lý danh mục hóa chất phòng','Thêm, sửa, khoá hoá chất ở tab Hoá chất của phòng (phòng đang chọn): đơn vị tính, khối lượng quy đổi cho đơn vị đếm, hạn dùng nội bộ (tháng), ngưỡng tồn tối thiểu / tối đa, định khu.\nLưu ý: chỉ hoá chất đã khai ở đây mới nhập kho được ở phòng. Khi đặt định khu, hệ thống chặn đặt hoá chất tương kỵ cùng kệ / tủ.','2026-09-02 19:06:20','2026-11-03 11:35:42'),(80,2,NULL,'category_standard_approve','Duyệt Danh Mục Chất Chuẩn Chung','Duyệt mã chất chuẩn đang Chờ duyệt trong Danh mục chất chuẩn công ty (nhập lại mật khẩu khi duyệt). Mã chờ duyệt hiện ở Trang chủ của người có quyền này.\nLưu ý: chỉ mã Đã duyệt mới được các phòng khai vào Chất chuẩn của phòng và dùng ở Nhập, Đề nghị, Dự trù.','2026-09-02 19:06:20','2026-11-03 11:35:42'),(82,2,NULL,'category_standard_dept_manage','Quản lý danh mục chất chuẩn phòng','Thêm, sửa, khoá chất chuẩn ở tab Chất chuẩn của phòng (phòng đang chọn): đơn vị tính, hạn dùng nội bộ (tháng), ngưỡng tồn tối thiểu / tối đa, định khu.\nLưu ý: chỉ chất chuẩn đã khai ở đây mới nhập kho được ở phòng.','2026-09-02 19:06:20','2026-11-03 11:35:42'),(83,3,NULL,'import_material_label','In Nhãn Vật Tư','In nhãn lô vật tư (có mã QR, mục đích sử dụng) từ nút In nhãn trên Sổ nhập vật tư, để dán lên hàng.','2026-09-02 19:06:20','2026-11-03 11:35:42'),(84,3,NULL,'import_chemical_label','In Nhãn Hoá Chất','In nhãn lô hoá chất 60 × 40 mm cho máy in Zebra (mã QR, cảnh báo an toàn, số biểu mẫu) từ nút In nhãn trên Sổ nhập hoá chất. Mỗi lần in được ghi vào Audit Trail.','2026-09-02 19:06:20','2026-11-03 11:35:42'),(88,4,NULL,'export_chemical_transfer','Lập Phiếu Chuyển Hoá Chất','Phòng đang giữ hàng cấp phát đề nghị chuyển hoá chất do phòng khác gửi tới: chọn lô của phòng mình và số lượng rồi Cấp phát (trừ tồn ngay), hoặc Từ chối cấp từng mục.\nLưu ý: lô chưa xác định hạn dùng nội bộ chỉ cấp được nguyên cả lô.','2026-09-02 19:06:20','2026-11-03 11:35:42'),(92,5,NULL,'inventory_material_balancing','Cân Đối Tồn Kho Vật Tư','Bấm Cân đối trên lô ở tab Theo mã xuất nhập để điều chỉnh tồn sổ sách cho khớp thực tế (nhập số + hoặc −, kèm lý do), khi có sai số cân, hao hụt hoặc đếm nhầm.\nLưu ý: tổng cân đối của một lô không vượt quá 5% lượng nhập và tồn không được âm.','2026-09-02 19:06:20','2026-11-03 11:35:42'),(93,5,NULL,'inventory_chemical_balancing','Cân Đối Tồn Kho Hoá Chất','Bấm Cân đối trên lô ở tab Theo mã xuất nhập để điều chỉnh tồn sổ sách cho khớp thực tế (nhập số + hoặc −, kèm lý do), khi có sai số cân, hao hụt hoặc đếm nhầm.\nLưu ý: tổng cân đối của một lô không vượt quá 5% lượng nhập và tồn không được âm.','2026-09-02 19:06:20','2026-11-03 11:35:42'),(95,5,NULL,'inventory_material_stocktake','Kiểm Kê Kho Vật Tư','Kiểm kê kho vật tư theo quý ở tab Kiểm kê định kỳ: mở phiếu (hệ thống chụp tồn sổ sách), nhập số thực đếm (quét QR trên nhãn), chốt phiếu để hệ thống tự cân đối phần lệch; huỷ phiếu đang đếm để mở lại.\nLưu ý: mỗi phòng mỗi quý chỉ mở một phiếu. Dòng lệch vượt giới hạn cân đối được đánh dấu Chờ Xử Lý thay vì tự cân đối.','2026-09-02 19:06:20','2026-11-03 11:35:42'),(96,5,NULL,'inventory_chemical_internalExpiry','Đặt Hạn Dùng Nội Bộ Hoá Chất','Xác định hạn dùng nội bộ cho lô hoá chất: chọn ngày mở nắp / đưa vào dùng, hạn = ngày đó + số tháng hạn dùng mặc định (không vượt hạn nhà sản xuất). Xác định lại được nhiều lần, mỗi lần ghi Audit Trail.\nLưu ý: lô chưa xác định hạn nội bộ chỉ chuyển được nguyên cả lô cho phòng khác.','2026-09-02 19:06:20','2026-11-03 11:35:42'),(97,5,NULL,'inventory_standard_internalExpiry','Đặt Hạn Dùng Nội Bộ Chất Chuẩn','Xác định hạn dùng nội bộ cho ống chuẩn: chọn ngày mở ống, hạn = ngày mở + số tháng hạn dùng (không vượt hạn nhà sản xuất).\nLưu ý: ống của chuẩn có hạn dùng mặc định mà chưa xác định hạn nội bộ thì chưa cấp phát và chưa dùng được.','2026-09-02 19:06:20','2026-11-03 11:35:42'),(98,5,NULL,'inventory_standard_weight','Nhận xét chuẩn ngoài giới hạn','Ở tab Kiểm soát khối lượng: nhập Khối lượng bì sau khi sử dụng cho ống có kiểm soát khối lượng, và ghi nhận xét cho ống có sai lệch ngoài giới hạn cho phép.','2026-09-02 19:06:20','2026-11-03 11:35:42'),(99,6,NULL,'estimate_material_delete','Huỷ Phiếu Dự Trù Vật Tư','Huỷ phiếu dự trù vật tư khi phiếu còn Nháp hoặc Bị từ chối (chưa trình ký).','2026-09-02 19:06:20','2026-11-03 11:35:42'),(100,6,NULL,'estimate_material_tracking','Theo Dõi Giao Hàng Dự Trù Vật Tư','Phía phòng đề nghị theo dõi mặt hàng dự trù đã duyệt: đánh dấu Hoàn thành khi đã nhận đủ hàng, đề nghị Huỷ mặt hàng không cần nữa, hoặc hoàn tác.\nLưu ý: huỷ một mặt hàng cần cả bộ phận mua hàng đồng ý.','2026-09-02 19:06:20','2026-11-03 11:35:42'),(101,6,NULL,'estimate_chemical_delete','Huỷ Phiếu Dự Trù Hoá Chất','Huỷ phiếu dự trù hoá chất khi phiếu còn Nháp hoặc Bị từ chối (chưa trình ký).','2026-09-02 19:06:20','2026-11-03 11:35:42'),(102,6,NULL,'estimate_chemical_tracking','Theo Dõi Giao Hàng Dự Trù Hoá Chất','Phía phòng đề nghị theo dõi mặt hàng dự trù đã duyệt: đánh dấu Hoàn thành khi đã nhận đủ hàng, đề nghị Huỷ mặt hàng không cần nữa, hoặc hoàn tác.\nLưu ý: huỷ một mặt hàng cần cả bộ phận mua hàng đồng ý.','2026-09-02 19:06:20','2026-11-03 11:35:42'),(103,6,NULL,'estimate_standard_delete','Huỷ Phiếu Dự Trù Chất Chuẩn','Huỷ phiếu dự trù chất chuẩn khi phiếu còn Nháp hoặc Bị từ chối (chưa trình ký).','2026-09-02 19:06:20','2026-11-03 11:35:42'),(104,6,NULL,'estimate_standard_tracking','Theo Dõi Giao Hàng Dự Trù Chất Chuẩn','Phía phòng đề nghị theo dõi mặt hàng dự trù đã duyệt: đánh dấu Hoàn thành khi đã nhận đủ hàng, đề nghị Huỷ mặt hàng không cần nữa, hoặc hoàn tác.\nLưu ý: huỷ một mặt hàng cần cả bộ phận mua hàng đồng ý.','2026-09-02 19:06:20','2026-11-03 11:35:42'),(105,5,NULL,'stability_standard_assess','Thực Hiện Đánh Giá Chuẩn Thứ Cấp','Ghi (hoặc sửa) kết quả đánh giá cho từng mốc của phiếu đánh giá hạn dùng CTC đang chạy, trên trang chi tiết phiếu.','2026-09-02 19:06:20','2026-11-03 11:35:42'),(106,5,NULL,'stability_standard_issue','Cấp Phát Chuẩn Thứ Cấp','Cấp phát lượng chuẩn để thử từng chỉ tiêu kiểm của một mốc đánh giá hạn dùng CTC (nút trên dòng mốc ở trang chi tiết phiếu).','2026-09-02 19:06:20','2026-11-03 11:35:42'),(107,5,NULL,'stability_standard_delete','Huỷ Phiếu / Mốc Đánh Giá Chuẩn Thứ Cấp','Huỷ hoặc mở lại phiếu đánh giá hạn dùng CTC; huỷ mốc đánh giá chưa có kết quả (mốc huỷ không tính vào tiến độ nhưng vẫn lưu trong lịch sử thay đổi).','2026-09-02 19:06:20','2026-11-03 11:35:42'),(108,8,NULL,'user_resetPassword','Reset Mật Khẩu User','Đặt lại mật khẩu tạm cho người dùng (quên mật khẩu, bị khoá do nhập sai): tài khoản được mở khoá ngay, người dùng phải đổi mật khẩu ở lần đăng nhập kế tiếp.\nLưu ý: mật khẩu tạm phải đủ độ phức tạp và không trùng 5 mật khẩu gần nhất của người đó.','2026-09-04 14:27:58','2026-11-03 11:35:42'),(110,4,NULL,'export_chemical_transfer_receive','Nhận Chuyển Hoá Chất Liên Phòng Ban','Phòng đề nghị nhận hoá chất mà phòng khác đã cấp: bấm Nhận, ghi kết luận kiểm tra và chọn định khu thật. Lô vào tồn của phòng nhận ngay, mã lô giữ mã gốc kèm hậu tố -CK1, -CK2...\nLưu ý: hoá chất phải được khai ở Hoá chất của phòng nhận trước khi bấm Nhận.','2026-09-05 15:13:13','2026-11-03 11:35:42'),(111,4,NULL,'export_chemical_transfer_return','Từ Chối Nhận Chuyển Hoá Chất','Phòng đề nghị từ chối nhận hoá chất đã được cấp (ví dụ hàng không đạt khi kiểm tra). Số lượng tự hoàn lại tồn cho phòng đã cấp.','2026-09-05 15:13:13','2026-11-03 11:35:42'),(112,4,NULL,'export_standard_transfer_receive','Nhận Chuyển Chất Chuẩn Liên Phòng Ban','Phòng đề nghị nhận chất chuẩn mà phòng khác đã cấp: bấm Nhận, ghi kết luận kiểm tra, chọn định khu thật, có thể đánh dấu chiết ống trước khi dùng. Ống vào tồn của phòng nhận ngay.\nLưu ý: chất chuẩn phải được khai ở Chất chuẩn của phòng nhận trước khi bấm Nhận.','2026-09-05 15:13:13','2026-11-03 11:35:42'),(113,4,NULL,'export_standard_transfer_return','Từ Chối Nhận Chuyển Chất Chuẩn','Phòng đề nghị từ chối nhận chất chuẩn đã được cấp (ví dụ không đạt khi kiểm tra). Số lượng tự hoàn lại tồn cho phòng đã cấp.','2026-09-05 15:13:13','2026-11-03 11:35:42'),(114,8,NULL,'role_manage','Tạo / Sửa Nhóm Quyền','Tạo nhóm quyền mới, đổi tên, sửa diễn giải và Loại Phụ Trách của nhóm quyền, xoá nhóm quyền.\nLưu ý: không xoá được nhóm quyền đang được gán cho người dùng.','2026-09-06 10:05:42','2026-11-03 11:35:42'),(115,5,NULL,'inventory_standard_expiryUpdate','Cập Nhật Hạn Dùng Chất Chuẩn','Cập nhật hạn dùng cho ống chuẩn có loại hạn Cần Retest định kỳ hoặc Check online (bấm badge trên bảng tồn) sau mỗi lần retest / tra cứu trực tuyến. Mỗi lần lưu giá trị cũ → mới, ghi chú và file đính kèm.','2026-09-06 10:09:27','2026-11-03 11:35:42'),(116,1,NULL,'materData_material_view','Xem Dữ Liệu Gốc Vật Tư','Quyền nền để xem các màn Dữ Liệu Gốc nhóm Vật Tư: Tên Vật Tư, Phân Loại, Trình Ký Đề Nghị CP Vật Tư. Chỉ xem, không thêm hay sửa được.\nLưu ý: chọn màn nào hiện trên menu bằng các quyền con \"Xem <màn hình>\" bên dưới; chỉ có quyền này mà không có quyền con thì không thấy màn nào.','2026-09-06 11:00:23','2026-11-03 11:35:42'),(122,1,NULL,'materData_chemical_view','Xem Dữ Liệu Gốc Hoá Chất','Quyền nền để xem các màn Dữ Liệu Gốc nhóm Hoá Chất: Đơn Chất, Nhóm Nguy Hại Bảng B, Hoá Chất. Chỉ xem, không thêm hay sửa được.\nLưu ý: chọn màn nào hiện trên menu bằng các quyền con \"Xem <màn hình>\" bên dưới; chỉ có quyền này mà không có quyền con thì không thấy màn nào.','2026-09-06 11:00:23','2026-11-03 11:35:42'),(128,1,NULL,'materData_standard_view','Xem Dữ Liệu Gốc Chất Chuẩn','Quyền nền để xem các màn Dữ Liệu Gốc nhóm Chất Chuẩn: Tên Chuẩn, Chỉ Tiêu Kiểm. Chỉ xem, không thêm hay sửa được.\nLưu ý: chọn màn nào hiện trên menu bằng các quyền con \"Xem <màn hình>\" bên dưới; chỉ có quyền này mà không có quyền con thì không thấy màn nào.','2026-09-06 11:00:23','2026-11-03 11:35:42'),(134,1,NULL,'materData_common_view','Xem Dữ Liệu Gốc Dùng Chung','Quyền nền để xem các màn Dữ Liệu Gốc dùng chung: Công Ty, Phòng Ban, Tổ, Đơn Vị Tính, Quy Cách Đóng Gói, Điều Kiện Bảo Quản, Nhà Sản Xuất, Nhà Cung Cấp, Trạng Thái, Tên Sản Phẩm, Định Khu, Đối Tượng. Chỉ xem, không thêm hay sửa được.\nLưu ý: chọn màn nào hiện trên menu bằng các quyền con \"Xem <màn hình>\" bên dưới; chỉ có quyền này mà không có quyền con thì không thấy màn nào.','2026-09-06 11:00:23','2026-11-03 11:35:42'),(140,3,NULL,'import_chemical_attachment_status','Đổi Trạng Thái File Đính Kèm Hoá Chất','Đổi trạng thái file đính kèm của phiếu nhập hoá chất giữa Đang sử dụng và Ngưng sử dụng (ví dụ CoA cũ đã thay). File không bị xoá, vẫn xem lại được.','2026-09-06 11:09:35','2026-11-03 11:35:42'),(141,3,NULL,'import_material_attachment_status','Đổi Trạng Thái File Đính Kèm Vật Tư','Đổi trạng thái file đính kèm của phiếu nhập vật tư giữa Đang sử dụng và Ngưng sử dụng. File không bị xoá, vẫn xem lại được.','2026-09-06 11:09:35','2026-11-03 11:35:42'),(142,3,NULL,'import_standard_attachment_status','Đổi Trạng Thái File Đính Kèm Chất Chuẩn','Đổi trạng thái file đính kèm của phiếu nhập chất chuẩn giữa Đang sử dụng và Ngưng sử dụng (ví dụ CoA cũ đã thay). File không bị xoá, vẫn xem lại được.','2026-09-06 11:09:35','2026-11-03 11:35:42'),(143,4,NULL,'export_material_transfer','Cấp Phát Vật Tư Liên Phòng Ban','Phòng đang giữ hàng cấp phát đề nghị liên phòng ban và đề nghị VPP do phòng khác gửi tới: chọn mã xuất nhập (lô) của phòng mình và số lượng rồi Cấp phát (trừ tồn ngay), hoặc Từ chối cấp từng mục.','2026-09-06 17:11:16','2026-11-03 11:35:42'),(144,4,NULL,'export_material_transfer_receive','Nhận Chuyển Vật Tư Liên Phòng Ban','Phòng đề nghị nhận vật tư mà phòng khác đã cấp: bấm Nhận, ghi kết luận kiểm tra và chọn định khu thật (bắt buộc). Lô vào tồn của phòng nhận ngay, mã lô giữ mã gốc kèm hậu tố -CK1, -CK2... để truy vết.','2026-09-06 17:11:16','2026-11-03 11:35:42'),(145,4,NULL,'export_material_transfer_return','Từ Chối Nhận Chuyển Vật Tư','Phòng đề nghị từ chối nhận vật tư đã được cấp (ví dụ hàng không đạt khi kiểm tra). Số lượng tự hoàn lại tồn cho phòng đã cấp.','2026-09-06 17:11:16','2026-11-03 11:35:42'),(146,3,NULL,'import_chemical_attachment_upload','Đính Kèm Thêm File Hoá Chất','Tải thêm file hồ sơ (CoA, hoá đơn, MSDS...) vào phiếu nhập hoá chất đã lập, tối đa 10MB mỗi file.','2026-09-08 07:24:40','2026-11-03 11:35:42'),(147,3,NULL,'import_material_attachment_upload','Đính Kèm Thêm File Vật Tư','Tải thêm file hồ sơ (hoá đơn, phiếu giao hàng, chứng nhận...) vào phiếu nhập vật tư đã lập.','2026-09-08 07:24:40','2026-11-03 11:35:42'),(148,3,NULL,'import_standard_attachment_upload','Đính Kèm Thêm File Chất Chuẩn','Tải thêm file hồ sơ (CoA, chứng nhận...) vào phiếu nhập chất chuẩn đã lập.','2026-09-08 07:24:40','2026-11-03 11:35:42'),(152,2,NULL,'category_material_periodic_manage','Quản Lý Đề Nghị Vật Tư Theo Chu Kỳ','Lập và quản lý 3 loại danh sách vật tư theo chu kỳ ở Danh Mục › Vật Tư (đề nghị nội bộ, đề nghị liên phòng ban, dự trù): thêm, sửa, khoá danh sách, đặt lịch (hằng tuần / tháng / quý hoặc mỗi N ngày, ngày bắt đầu) và tạo phiếu ngay từ danh sách.\nLưu ý: đến hạn, hệ thống tự tạo phiếu ở trạng thái Lưu tạm / Nháp để người lập kiểm tra rồi gửi đi.','2026-09-14 15:29:34','2026-11-03 11:35:42'),(153,4,NULL,'export_material_quarantine','Cách Ly / Huỷ Vật Tư Hỏng','Bước 1 và 3 của quy trình vật tư hỏng ở tab Cách ly - Loại bỏ - Huỷ: lập phiếu Cách ly (chọn mã xuất nhập, số lượng, định khu Chờ Quyết Định, lý do; hàng bị trừ tồn ngay) và ghi nhận Huỷ khi đã tiêu huỷ thực tế (ghi phương pháp, nhập lại mật khẩu).','2026-09-23 13:52:06','2026-11-03 11:35:42'),(154,4,NULL,'export_material_quarantine_decide','Quyết Định Loại Bỏ Vật Tư Hỏng','Bước 2 của quy trình vật tư hỏng: với vật tư đang cách ly, quyết định Loại bỏ (chuyển sang định khu Loại Bỏ/Chờ Huỷ, không quay lại kho được) hoặc Trả về kho (cộng lại tồn); ghi căn cứ và nhập lại mật khẩu.\nLưu ý: phiếu cách ly chờ quyết định hiện ở Trang chủ của người có quyền này.','2026-09-23 13:52:06','2026-11-03 11:35:42'),(155,4,NULL,'export_material_issue_lot_adjust','Điều Chỉnh Mã Xuất Nhập Khi Cấp Phát Vật Tư','Khi cấp phát vật tư, được chọn mã xuất nhập (lô) khác với lô hệ thống đề xuất theo FEFO/FIFO, hoặc thêm lô khác.\nLưu ý: không có quyền này thì chỉ cấp được từ đúng các lô hệ thống đề xuất.','2026-10-13 11:49:49','2026-11-03 11:35:42'),(156,4,NULL,'export_material_update','Điều Chỉnh Sổ Sử Dụng Vật Tư','Sửa hoặc khoá một dòng ghi sai ở tab Sổ cấp phát (số lượng, mục đích, ghi chú). Mỗi lần điều chỉnh được lưu lịch sử.\nLưu ý: dòng sinh từ phiếu cách ly chỉ xử lý ở tab Cách ly - Loại bỏ - Huỷ; dòng cấp phát liên phòng ban không sửa được.','2026-10-15 14:24:43','2026-11-03 11:35:42'),(157,4,NULL,'export_material_issue_amount_adjust','Điều Chỉnh Số Lượng Khi Cấp Phát Vật Tư','Khi cấp phát vật tư, được nhập số lượng cấp khác số hệ thống đề xuất (cấp một phần, cấp khác số đề nghị).\nLưu ý: không có quyền này thì phải cấp đúng số đề xuất. Mỗi lô vẫn chỉ được cấp vượt tối đa 5%.','2026-10-16 08:46:39','2026-11-03 11:35:42'),(158,8,NULL,'login_history_view','Xem Lịch Sử Đăng Nhập','Thấy mục Lịch Sử Đăng Nhập › Toàn Hệ Thống: lượt đăng nhập của mọi tài khoản (thành công, sai mật khẩu, bị khoá), các phiên đang mở và xuất Excel.\nLưu ý: không có quyền này vẫn xem được lịch sử đăng nhập của chính mình ở mục Của Tôi.','2026-10-19 09:52:55','2026-11-03 11:35:42'),(159,6,NULL,'estimate_material_purchasing','Tiếp Nhận Xử Lý Dự Trù Vật Tư','Dành cho bộ phận mua hàng: xem tab Đơn dự trù đã được phê duyệt của mọi phòng ban, bấm Tiếp nhận phiếu, cập nhật Ngày hẹn đáp ứng cho từng tháng của từng vật tư, đồng ý hoặc không đồng ý huỷ mặt hàng.\nLưu ý: chỉ có tác dụng khi đang chọn đúng phòng mua hàng (Cung Ứng / Hành Chánh) ở thanh trên cùng. Phiếu chờ tiếp nhận hiện ở Trang chủ.','2026-10-21 10:34:58','2026-11-03 11:35:42'),(160,6,NULL,'estimate_chemical_purchasing','Tiếp Nhận Xử Lý Dự Trù Hoá Chất','Dành cho bộ phận mua hàng: xem tab Đơn dự trù đã được phê duyệt của mọi phòng ban, bấm Tiếp nhận phiếu, cập nhật Ngày hẹn đáp ứng cho từng tháng của từng hoá chất, đồng ý hoặc không đồng ý huỷ mặt hàng.\nLưu ý: hoá chất luôn do Cung Ứng mua; chỉ có tác dụng khi đang chọn phòng Cung Ứng ở thanh trên cùng.','2026-10-21 10:34:58','2026-11-03 11:35:42'),(161,6,NULL,'estimate_standard_purchasing','Tiếp Nhận Xử Lý Dự Trù Chất Chuẩn','Dành cho bộ phận mua hàng: xem tab Đơn dự trù đã được phê duyệt của mọi phòng ban, bấm Tiếp nhận phiếu, cập nhật Ngày hẹn đáp ứng cho từng tháng của từng chất chuẩn, đồng ý hoặc không đồng ý huỷ mặt hàng.\nLưu ý: chất chuẩn do Cung Ứng mua; chỉ có tác dụng khi đang chọn phòng Cung Ứng ở thanh trên cùng.','2026-10-21 10:34:58','2026-11-03 11:35:42'),(162,6,45,'estimate_material_tab_list','Tab Danh Sách Phiếu','Xem tab Danh sách phiếu: các phiếu dự trù vật tư của phòng đang chọn và trạng thái ký.','2026-10-21 14:47:08','2026-11-10 17:37:47'),(163,6,45,'estimate_material_tab_tracking','Tab Theo Dõi Dự Trù','Xem tab Theo dõi dự trù: từng mặt hàng đã duyệt của phòng với ngày mong muốn, ngày hẹn đáp ứng, trạng thái và cột Trao đổi.','2026-10-21 14:47:08','2026-11-10 17:37:47'),(164,6,45,'estimate_material_tab_watchlist','Tab Danh Sách Vật Tư Cần Dự Trù','Xem tab Danh sách vật tư cần dự trù: vật tư dưới ngưỡng tồn tối thiểu, do người dùng đề nghị, hoặc thiếu ở Khả dụng tháng tới; tick chọn để lập phiếu dự trù nhanh.','2026-10-21 14:47:08','2026-11-10 17:37:47'),(166,6,45,'estimate_material_tab_approved','Tab Đơn Dự Trù Đã Được Phê Duyệt','Xem tab Đơn dự trù đã được phê duyệt: phiếu dự trù vật tư đã duyệt của mọi phòng ban chờ bộ phận mua hàng tiếp nhận và hẹn ngày đáp ứng.\nLưu ý: tab chỉ hiện khi đang chọn phòng mua hàng và có thêm quyền Tiếp Nhận Xử Lý Dự Trù Vật Tư.','2026-10-21 14:47:08','2026-11-10 17:37:47'),(167,2,5,'category_material_tab_company','Tab Danh mục vật tư công ty','Xem tab Danh mục vật tư công ty: toàn bộ mã vật tư dùng chung công ty với phân loại, bộ phận mua hàng, thời gian đặt hàng, trạng thái duyệt và lịch sử thay đổi.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(168,2,5,'category_material_tab_department','Tab Vật tư của phòng','Xem tab Vật tư của phòng: các vật tư phòng đang chọn đã khai, kèm đơn vị tính, phân loại của phòng, ngưỡng tồn, định khu.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(169,2,5,'category_material_tab_internal','Tab DS đề nghị nội bộ theo chu kỳ','Xem tab DS đề nghị nội bộ theo chu kỳ: các danh sách tự tạo đề nghị cấp phát nội bộ theo lịch (có thể gắn với một Đối tượng).','2026-10-21 14:55:11','2026-11-10 17:37:47'),(170,2,5,'category_material_tab_external','Tab DS đề nghị liên phòng ban theo chu kỳ','Xem tab DS đề nghị liên phòng ban theo chu kỳ: các danh sách tự tạo đề nghị gửi phòng ban khác (kể cả VPP đến Hành Chánh) theo lịch.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(171,2,5,'category_material_tab_estimate','Tab DS dự trù theo chu kỳ','Xem tab DS dự trù theo chu kỳ: các danh sách tự lập phiếu dự trù Nháp theo lịch, cho tháng tạo phiếu hoặc 1 - 3 tháng sau.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(172,2,9,'category_chemical_tab_company','Tab Danh mục hoá chất công ty','Xem tab Danh mục hoá chất công ty: mã hoá chất dùng chung với nhà sản xuất, phân loại NĐ 24/2026, cờ đã khai báo Cổng thông tin quốc gia, thời gian đặt hàng, trạng thái duyệt.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(173,2,9,'category_chemical_tab_department','Tab Hoá chất của phòng','Xem tab Hoá chất của phòng: các hoá chất phòng đang chọn đã khai, kèm đơn vị, khối lượng quy đổi, hạn dùng nội bộ, ngưỡng tồn, định khu.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(174,2,13,'category_standard_tab_company','Tab Danh mục chất chuẩn công ty','Xem tab Danh mục chất chuẩn công ty: mã chất chuẩn dùng chung với nguồn gốc / nhà sản xuất, phân nhóm chuẩn, hạn dùng mặc định, thời gian đặt hàng, trạng thái duyệt.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(175,2,13,'category_standard_tab_department','Tab Chất chuẩn của phòng','Xem tab Chất chuẩn của phòng: các chất chuẩn phòng đang chọn đã khai, kèm đơn vị, hạn dùng nội bộ, ngưỡng tồn, định khu.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(176,3,17,'import_material_tab_book','Tab Sổ nhập vật tư','Xem tab Sổ nhập vật tư: mọi lô vật tư đã nhập của phòng với tình trạng kiểm tra; nơi lập phiếu nhập, điều chỉnh, in nhãn, xem file đính kèm.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(177,3,17,'import_material_tab_check','Tab Chờ kiểm tra','Xem tab Chờ kiểm tra: các lô vật tư vừa nhập, đang nằm trong khu Biệt Trữ chờ xác nhận kiểm tra.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(178,3,21,'import_chemical_tab_book','Tab Sổ nhập hoá chất','Xem tab Sổ nhập hoá chất: toàn bộ lô đã nhập của phòng (kể cả lô nhận chuyển từ phòng khác) với tình trạng kiểm tra, nút điều chỉnh, in nhãn, file đính kèm.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(179,3,21,'import_chemical_tab_report','Tab Báo cáo nhập hoá chất','Xem tab Báo cáo nhập hoá chất: tổng lượng nhập theo mã danh mục trong khoảng thời gian (quy ra kg), tách hoá chất mua và hoá chất nhận chuyển.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(180,3,21,'import_chemical_tab_check','Tab Nhập hoá chất','Xem tab Nhập hoá chất: nơi lập phiếu nhập và kiểm tra các lô đang Chờ kiểm tra.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(181,3,25,'import_standard_tab_book','Tab Sổ nhập chất chuẩn','Xem tab Sổ nhập chất chuẩn: toàn bộ phiếu nhập ống chuẩn của phòng, lọc theo ngày nhập, từ khoá, mã vạch, phân nhóm chuẩn.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(182,3,25,'import_standard_tab_check','Tab Nhập chất chuẩn','Xem tab Nhập chất chuẩn: nơi nhập ống chuẩn và kiểm tra các ống đang Chờ kiểm tra.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(183,4,29,'export_material_tab_periodic','Tab Đề nghị nội bộ - Theo định kỳ','Xem tab Đề nghị nội bộ - Theo định kỳ: các đề nghị cấp phát nội bộ hệ thống tự tạo từ danh sách nội bộ theo chu kỳ (không lập tay ở tab này).','2026-10-21 14:55:11','2026-11-10 17:37:47'),(184,4,29,'export_material_tab_risk_assessment','Tab Đề nghị nội bộ - Theo ĐG rủi ro','Xem tab Đề nghị nội bộ - Theo ĐG rủi ro: các đề nghị cấp phát nội bộ lập tay theo kết quả đánh giá rủi ro.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(185,4,29,'export_material_tab_regular','Tab Đề nghị nội bộ - Thường quy','Xem tab Đề nghị nội bộ - Thường quy: các đề nghị cấp phát nội bộ thường ngày, lập tay.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(187,4,29,'export_material_tab_transfer','Tab Đề nghị liên phòng ban - Phòng ban khác','Xem tab Đề nghị liên phòng ban - Phòng ban khác: đề nghị phòng mình gửi đi xin vật tư và đề nghị phòng khác gửi tới phòng mình.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(188,4,29,'export_material_tab_prepare','Tab Chờ cấp phát','Xem tab Chờ cấp phát: các dòng đề nghị đã duyệt (nội bộ, liên phòng ban và VPP gửi tới phòng mình) còn phải cấp, kèm tồn khả dụng và lô gợi ý.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(189,4,29,'export_material_tab_book','Tab Sổ cấp phát','Xem tab Sổ cấp phát: nhật ký mọi lần vật tư rời kho của phòng (sử dụng, loại bỏ, cấp phát liên phòng ban).','2026-10-21 14:55:11','2026-11-10 17:37:47'),(190,4,29,'export_material_tab_quarantine','Tab Cách ly - Loại bỏ - Huỷ','Xem tab Cách ly - Loại bỏ - Huỷ: các phiếu cách ly vật tư hỏng theo từng bước (chờ quyết định, loại bỏ - chờ huỷ, đã huỷ, trả về kho).','2026-10-21 14:55:11','2026-11-10 17:37:47'),(191,4,29,'export_material_tab_late','Tab Ghi nhận cấp phát trễ','Xem tab Ghi nhận cấp phát trễ: báo cáo theo tháng các dòng đề nghị không cấp kịp ngày mong muốn và nguyên nhân (duyệt trễ, thiếu tồn, cấp phát trễ).','2026-10-21 14:55:11','2026-11-10 17:37:47'),(192,4,33,'export_chemical_tab_book','Tab Sổ sử dụng hoá chất','Xem tab Sổ sử dụng hoá chất: nhật ký mọi lần hoá chất rời kho của phòng (sử dụng, loại bỏ, chuyển cho phòng khác) với người sử dụng, người kiểm tra, mục đích.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(193,4,33,'export_chemical_tab_draft','Tab Sử Dụng Hoá Chất','Xem tab Sử Dụng Hoá Chất: nơi ghi phiếu sử dụng và các dòng đang nằm ở Phiếu Tạm (đã chọn nhưng chưa ghi thật).','2026-10-21 14:55:11','2026-11-10 17:37:47'),(194,4,33,'export_chemical_tab_banned','Tab Hoá chất cấm','Xem tab Hoá chất cấm: sổ theo dõi riêng từng lần nhập, xuất và tồn cộng dồn của hoá chất cấm (nhóm 11). Chỉ để xem, tra cứu và in.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(195,4,33,'export_chemical_tab_request','Tab Đề nghị chuyển liên phòng ban','Xem tab Đề nghị chuyển liên phòng ban: đề nghị xin hoá chất phòng mình gửi đi và đề nghị phòng khác gửi tới phòng mình.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(196,4,33,'export_chemical_tab_report','Tab Báo cáo theo khoảng thời gian','Xem tab Báo cáo theo khoảng thời gian: tổng lượng hoá chất đã sử dụng theo mã danh mục, số lượt xuất và số lượng quy đổi ra kg.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(197,4,37,'export_standard_tab_book','Tab Sổ sử dụng chất chuẩn','Xem tab Sổ sử dụng chất chuẩn: mọi phiếu sử dụng chuẩn của phòng (kèm dòng Loại bỏ sinh từ phiếu cách ly), lọc theo ngày, mã ống, tên chuẩn, số lô, chỉ tiêu.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(198,4,37,'export_standard_tab_request','Tab Đề nghị cấp phát chuẩn nội bộ','Xem tab Đề nghị cấp phát chuẩn nội bộ: đề nghị của các tổ, chia 3 tab con Chưa gửi / Chờ xử lý / Đã xử lý.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(199,4,37,'export_standard_tab_transfer','Tab Đề nghị cấp phát chuẩn liên phòng ban','Xem tab Đề nghị cấp phát chuẩn liên phòng ban: đề nghị phòng mình gửi đi và đề nghị phòng khác gửi tới phòng mình.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(200,5,41,'inventory_material_tab_code','Tab Theo mã xuất nhập','Xem tab Theo mã xuất nhập: tồn từng lô theo kỳ (đầu kỳ, nhập, sử dụng, cách ly / huỷ, cuối kỳ), hạn dùng, vị trí; nơi có nút Cân đối và Biểu đồ.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(201,5,41,'inventory_material_tab_material','Tab Tồn theo mã vật tư','Xem tab Tồn theo mã vật tư: tổng tồn gộp các lô theo vật tư, hạn gần nhất, nhà sản xuất; lọc theo phân loại vật tư.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(202,5,41,'inventory_material_tab_zone','Tab Tồn kho theo vị trí','Xem tab Tồn kho theo vị trí: sơ đồ kho - kệ - vị trí, bấm vào vị trí để xem lô đang để ở đó.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(203,5,41,'inventory_material_tab_next','Tab Khả dụng tháng tới','Xem tab Khả dụng tháng tới: tồn hiện có có đủ cho nhu cầu theo chu kỳ của tháng tới không, thiếu bao nhiêu, lượng nên dự trù.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(204,5,41,'inventory_material_tab_check','Tab Kiểm kê định kỳ','Xem tab Kiểm kê định kỳ: phiếu kiểm kê theo quý của phòng, số thực đếm và chênh lệch.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(205,5,42,'inventory_chemical_tab_code','Tab Theo mã xuất nhập','Xem tab Theo mã xuất nhập: tồn từng lô theo kỳ, hạn dùng, hạn nội bộ, vị trí thực tế; nơi có nút Cân đối, Cách ly, Biểu đồ, file đính kèm, xác định hạn nội bộ.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(206,5,42,'inventory_chemical_tab_chemical','Tab Theo hoá chất','Xem tab Theo hoá chất: tổng tồn gộp các lô theo hoá chất, hạn gần nhất, tồn theo từng số lô.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(207,5,42,'inventory_chemical_tab_zone','Tab Theo định khu','Xem tab Theo định khu: sơ đồ kho - kệ - vị trí, bấm vào vị trí để xem lô đang để ở đó.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(208,5,42,'inventory_chemical_tab_expiring','Tab Cận hạn dùng','Xem tab Cận hạn dùng: các lô có hạn rơi vào 6 tháng tới hoặc đã quá hạn, lọc nhanh theo mốc ≤ 3 tháng / 1 tháng / 2 tuần / 1 tuần.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(209,5,42,'inventory_chemical_tab_internal','Tab Chưa có hạn nội bộ','Xem tab Chưa có hạn nội bộ: các lô của hoá chất có hạn dùng mặc định nhưng chưa xác định hạn dùng nội bộ.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(210,5,43,'inventory_standard_tab_code','Tab Theo mã ống chuẩn','Xem tab Theo mã ống chuẩn: mỗi ống một dòng với tồn theo kỳ, hạn dùng; nơi có nút Cách ly và Xác định hạn nội bộ.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(211,5,43,'inventory_standard_tab_standard','Tab Theo chất chuẩn','Xem tab Theo chất chuẩn: gộp các ống theo chất chuẩn (số ống còn tồn / tổng số ống), tồn theo kỳ, hạn gần nhất.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(212,5,43,'inventory_standard_tab_zone','Tab Theo định khu','Xem tab Theo định khu: sơ đồ kho - kệ - vị trí và các ống đang để ở mỗi vị trí.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(213,5,43,'inventory_standard_tab_expiring','Tab Cận hạn dùng','Xem tab Cận hạn dùng: các ống có hạn rơi vào 6 tháng tới hoặc đã quá hạn, lọc nhanh theo mốc ≤ 3 tháng / 1 tháng / 2 tuần / 1 tuần.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(214,5,43,'inventory_standard_tab_internal','Tab Chưa có hạn nội bộ','Xem tab Chưa có hạn nội bộ: các ống của chuẩn có hạn dùng mặc định nhưng chưa xác định hạn dùng nội bộ.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(215,5,43,'inventory_standard_tab_weight','Tab Kiểm soát khối lượng','Xem tab Kiểm soát khối lượng: so lượng chuẩn thực có trong ống với tổng lượng đã ghi sử dụng để phát hiện hao hụt bất thường.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(216,6,49,'estimate_chemical_tab_list','Tab Danh sách phiếu','Xem tab Danh sách phiếu: các phiếu dự trù hoá chất của phòng đang chọn và trạng thái ký.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(217,6,49,'estimate_chemical_tab_tracking','Tab Theo dõi dự trù','Xem tab Theo dõi dự trù: từng mặt hàng đã duyệt của phòng với ngày mong muốn, ngày hẹn đáp ứng, trạng thái và cột Trao đổi.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(219,6,49,'estimate_chemical_tab_approved','Tab Đơn dự trù đã được phê duyệt','Xem tab Đơn dự trù đã được phê duyệt: phiếu dự trù hoá chất đã duyệt của mọi phòng ban chờ Cung Ứng tiếp nhận và hẹn ngày đáp ứng.\nLưu ý: tab chỉ hiện khi đang chọn phòng Cung Ứng và có thêm quyền Tiếp Nhận Xử Lý Dự Trù Hoá Chất.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(220,6,53,'estimate_standard_tab_list','Tab Danh sách phiếu','Xem tab Danh sách phiếu: các phiếu dự trù chất chuẩn của phòng đang chọn và trạng thái ký.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(221,6,53,'estimate_standard_tab_tracking','Tab Theo dõi dự trù','Xem tab Theo dõi dự trù: từng mặt hàng đã duyệt của phòng với ngày mong muốn, ngày hẹn đáp ứng, trạng thái và cột Trao đổi.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(223,6,53,'estimate_standard_tab_approved','Tab Đơn dự trù đã được phê duyệt','Xem tab Đơn dự trù đã được phê duyệt: phiếu dự trù chất chuẩn đã duyệt của mọi phòng ban chờ Cung Ứng tiếp nhận và hẹn ngày đáp ứng.\nLưu ý: tab chỉ hiện khi đang chọn phòng Cung Ứng và có thêm quyền Tiếp Nhận Xử Lý Dự Trù Chất Chuẩn.','2026-10-21 14:55:11','2026-11-10 17:37:47'),(224,6,163,'estimate_material_chat','Trao Đổi Theo Dõi Dự Trù','Gửi tin nhắn trao đổi giữa phòng đề nghị và bộ phận mua hàng ở cột Trao đổi của từng vật tư trong tab Theo dõi dự trù.','2026-10-21 15:43:15','2026-11-03 11:35:42'),(225,6,217,'estimate_chemical_chat','Trao Đổi Theo Dõi Dự Trù','Gửi tin nhắn trao đổi giữa phòng đề nghị và bộ phận mua hàng ở cột Trao đổi của từng hoá chất trong tab Theo dõi dự trù.','2026-10-21 15:43:15','2026-11-03 11:35:42'),(226,6,221,'estimate_standard_chat','Trao Đổi Theo Dõi Dự Trù','Gửi tin nhắn trao đổi giữa phòng đề nghị và bộ phận mua hàng ở cột Trao đổi của từng chất chuẩn trong tab Theo dõi dự trù.','2026-10-21 15:43:15','2026-11-03 11:35:42'),(227,4,NULL,'export_material_calibration_confirm','Xác Nhận Hiệu Chuẩn Vật Tư','Ký xác nhận Đạt / Không đạt cho từng đơn vị vật tư được đề nghị hiệu chuẩn, ở tab Xác nhận hiệu chuẩn của Sử Dụng Vật Tư (nhập lại mật khẩu). Phần Không đạt của phiếu hiệu chuẩn trước cấp phát tự chuyển sang Cách ly; chỉ phần Đạt mới cấp phát được.\nLưu ý: người đề nghị chọn Phòng + Người xác nhận khi gửi phiếu - chỉ người được chọn, đang làm việc ở đúng phòng đó, mới ký được. Phiếu chưa chọn người xác nhận thì phòng QA cùng công ty ký.','2026-10-21 16:08:50','2026-11-14 17:05:30'),(228,4,29,'export_material_tab_calibration','Tab Xác nhận hiệu chuẩn','Xem tab Xác nhận hiệu chuẩn: các đề nghị hiệu chuẩn vật tư đang chờ QA xác nhận và kết quả đã xác nhận.','2026-10-21 16:08:50','2026-11-10 17:37:47'),(229,4,NULL,'export_chemical_quarantine','Cách Ly / Huỷ Hoá Chất Hỏng','Bước 1 và 3 của quy trình hoá chất hỏng: bấm Cách ly trên lô ở Tồn Kho Hoá Chất (số lượng, định khu Chờ Quyết Định, lý do; hàng bị trừ tồn ngay) và ghi nhận Huỷ ở tab Cách ly - Loại bỏ - Huỷ khi đã tiêu huỷ thực tế (nhập lại mật khẩu).','2026-10-23 12:29:08','2026-11-03 11:35:42'),(230,4,NULL,'export_chemical_quarantine_decide','Quyết Định Loại Bỏ Hoá Chất Hỏng','Bước 2 của quy trình hoá chất hỏng: với hoá chất đang cách ly, quyết định Loại bỏ (chuyển sang định khu Loại Bỏ/Chờ Huỷ, không quay lại kho được) hoặc Trả về kho (cộng lại tồn); ghi căn cứ và nhập lại mật khẩu.\nLưu ý: phiếu cách ly chờ quyết định hiện ở Trang chủ của người có quyền này.','2026-10-23 12:29:08','2026-11-03 11:35:42'),(231,4,33,'export_chemical_tab_quarantine','Tab Cách ly - Loại bỏ - Huỷ','Xem tab Cách ly - Loại bỏ - Huỷ: các phiếu cách ly hoá chất hỏng theo từng bước.','2026-10-23 12:29:08','2026-11-10 17:37:47'),(232,6,49,'estimate_chemical_tab_watchlist','Tab Danh sách hoá chất cần dự trù','Xem tab Danh sách hoá chất cần dự trù: hoá chất có tồn dưới ngưỡng tồn tối thiểu của phòng; tick chọn để lập phiếu dự trù nhanh.','2026-10-23 16:05:27','2026-11-10 17:37:47'),(233,6,53,'estimate_standard_tab_watchlist','Tab Danh sách chất chuẩn cần dự trù','Xem tab Danh sách chất chuẩn cần dự trù: chất chuẩn có tồn dưới ngưỡng tồn tối thiểu của phòng; tick chọn để lập phiếu dự trù nhanh.','2026-10-23 16:05:27','2026-11-10 17:37:47'),(234,4,NULL,'export_standard_quarantine','Cách Ly / Huỷ Chất Chuẩn Hỏng','Bước 1 và 3 của quy trình ống chuẩn hỏng: bấm Cách ly trên ống ở Tồn Kho Chất Chuẩn (số lượng, định khu Chờ Quyết Định, lý do; trừ tồn ngay), sửa phiếu đang chờ quyết định, và ghi nhận Huỷ khi đã tiêu huỷ thực tế (nhập lại mật khẩu).','2026-10-26 10:03:58','2026-11-03 11:35:42'),(235,4,NULL,'export_standard_quarantine_decide','Quyết Định Loại Bỏ Chất Chuẩn Hỏng','Bước 2 của quy trình ống chuẩn hỏng: với ống đang cách ly, quyết định Loại bỏ (chuyển sang định khu Loại Bỏ/Chờ Huỷ, không quay lại kho được) hoặc Trả về kho (cộng lại tồn, chọn vị trí đặt lại); ghi căn cứ và nhập lại mật khẩu.\nLưu ý: phiếu cách ly chờ quyết định hiện ở Trang chủ của người có quyền này.','2026-10-26 10:03:58','2026-11-03 11:35:42'),(236,4,37,'export_standard_tab_quarantine','Tab Cách ly - Loại bỏ - Huỷ','Xem tab Cách ly - Loại bỏ - Huỷ: các phiếu cách ly ống chuẩn hỏng theo từng bước.','2026-10-26 10:03:58','2026-11-10 17:37:47'),(237,5,42,'inventory_chemical_tab_threshold','Tab Đối chiếu ngưỡng PL IV','Xem tab Đối chiếu ngưỡng PL IV: tổng tồn trữ toàn công ty so với ngưỡng Phụ lục IV NĐ 24/2026 (Bảng A theo hoạt chất, Bảng B theo hỗn hợp), để biết cơ sở có phải xây dựng Kế hoạch phòng ngừa, ứng phó sự cố hoá chất không. Chỉ để xem.','2026-10-26 14:12:49','2026-11-10 17:37:47'),(238,4,37,'export_standard_tab_use','Tab Sử dụng chuẩn','Xem tab Sử dụng chuẩn (tab mở mặc định): các ống kho đã cấp cho tổ mà chưa lập phiếu sử dụng; nơi bấm Sử dụng để ghi phiếu.','2026-10-27 14:52:53','2026-11-10 17:37:47'),(239,2,NULL,'category_material_lead_time','Điều Chỉnh Thời Gian Đặt Hàng Vật Tư','Sửa Thời gian đặt hàng (số ngày từ lúc đặt tới lúc hàng về) của mã vật tư do Cung Ứng mua trong Danh mục vật tư công ty, bằng nút ✎ ở cột Thời Gian Đặt Hàng. Không làm mã phải duyệt lại.\nLưu ý: khi có mã mới chưa khai số ngày, người có quyền này nhận thẻ nhắc ở Trang chủ.','2026-10-28 14:28:57','2026-11-03 11:35:42'),(240,2,NULL,'category_chemical_lead_time','Điều Chỉnh Thời Gian Đặt Hàng Hoá Chất','Sửa Thời gian đặt hàng (số ngày từ lúc đặt tới lúc hàng về) của mã hoá chất trong Danh mục hoá chất công ty, bằng nút ✎ ở cột Thời Gian Đặt Hàng. Không làm mã phải duyệt lại.\nLưu ý: khi có mã mới chưa khai số ngày, người có quyền này nhận thẻ nhắc ở Trang chủ.','2026-10-28 14:28:57','2026-11-03 11:35:42'),(241,2,NULL,'category_standard_lead_time','Điều Chỉnh Thời Gian Đặt Hàng Chất Chuẩn','Sửa Thời gian đặt hàng (số ngày từ lúc đặt tới lúc hàng về) của mã chất chuẩn trong Danh mục chất chuẩn công ty, bằng nút ✎ ở cột Thời Gian Đặt Hàng. Không làm mã phải duyệt lại.\nLưu ý: khi có mã mới chưa khai số ngày, người có quyền này nhận thẻ nhắc ở Trang chủ.','2026-10-28 14:28:57','2026-11-03 11:35:42'),(242,1,NULL,'materData_transferSign_view','Xem Trình Ký Liên Phòng Ban','Thấy mục Trình Ký Đề Nghị Liên Phòng Ban trên menu Dữ Liệu Gốc và xem các bước ký mà đề nghị chuyển vật tư giữa các phòng ban và đề nghị VPP đến Hành Chánh phải đi qua (khai riêng theo loại đề nghị và công ty). Chỉ xem.','2026-10-31 10:40:34','2026-11-03 11:35:42'),(243,1,NULL,'materData_transferSign_create','Thêm Bước Ký Liên Phòng Ban','Thêm bước ký mới ở màn Trình Ký Đề Nghị Liên Phòng Ban: loại đề nghị (VPP đến HC hoặc liên phòng ban khác), công ty của phòng đề nghị, thứ tự bước, vai trò ký và phạm vi phòng ban của người ký.\nLưu ý: công ty chưa khai bước ký nào thì đề nghị đi thẳng tới phòng được đề nghị, không qua bước ký.','2026-10-31 10:40:34','2026-11-03 11:35:42'),(244,1,NULL,'materData_transferSign_update','Sửa Bước Ký Liên Phòng Ban','Sửa bước ký đã khai ở màn Trình Ký Đề Nghị Liên Phòng Ban (đổi thứ tự bước, vai trò ký, phạm vi phòng ban...).','2026-10-31 10:40:34','2026-11-03 11:35:42'),(245,1,NULL,'materData_transferSign_deActive','Khoá Bước Ký Liên Phòng Ban','Khoá bước ký ở màn Trình Ký Đề Nghị Liên Phòng Ban để ngừng áp dụng, hoặc mở khoá để dùng lại. Bước ký không bị xoá hẳn.','2026-10-31 10:40:34','2026-11-03 11:35:42'),(246,1,NULL,'materData_initialData_upload','Đính Kèm File Khởi Tạo Dữ Liệu','Thấy mục Khởi Tạo Dữ Liệu trên menu Dữ Liệu Gốc và đính kèm các file Excel khởi tạo dữ liệu mà phòng ban đã điền (dùng khi triển khai hệ thống lần đầu).\nLưu ý: file chỉ được lưu để Admin xem, tải về, làm sạch rồi tự nạp; đính kèm không ghi dữ liệu vào hệ thống. Tải file mẫu chỉ dành cho Admin.','2026-11-02 09:13:02','2026-11-03 11:35:42'),(247,2,9,'category_chemical_tab_product','Tab Danh sách hoá chất theo sản phẩm','Xem tab Danh sách hoá chất theo sản phẩm: các gói Sản phẩm + Chỉ tiêu và hoá chất cần dùng của phòng (dùng ở Cách 3 khi ghi phiếu Sử Dụng Hoá Chất).','2026-11-02 15:42:55','2026-11-10 17:37:47'),(248,2,NULL,'category_chemical_product_manage','Quản lý danh sách hoá chất theo sản phẩm','Thêm, sửa, khoá gói Sản phẩm + Chỉ tiêu và danh sách hoá chất cần dùng (kèm lượng dùng gợi ý) của phòng đang chọn, ở tab Danh sách hoá chất theo sản phẩm.\nLưu ý: gói chỉ gồm hoá chất phòng đã khai ở tab Hoá chất của phòng; mỗi cặp Sản phẩm + Chỉ tiêu chỉ có một gói đang dùng.','2026-11-02 15:42:56','2026-11-03 11:35:42'),(249,2,13,'category_standard_tab_product','Tab Danh sách chất chuẩn theo sản phẩm','Xem tab Danh sách chất chuẩn theo sản phẩm: các gói Sản phẩm + Chỉ tiêu và chất chuẩn cần dùng của phòng (dùng khi lập đề nghị cấp phát chuẩn nội bộ).','2026-11-02 16:12:38','2026-11-10 17:37:47'),(250,2,NULL,'category_standard_product_manage','Quản lý danh sách chất chuẩn theo sản phẩm','Thêm, sửa, khoá gói Sản phẩm + Chỉ tiêu và danh sách chất chuẩn cần dùng của phòng đang chọn, ở tab Danh sách chất chuẩn theo sản phẩm.','2026-11-02 16:12:39','2026-11-03 11:35:42'),(251,1,116,'materData_material_view_materialName','Xem Tên Vật Tư','Thấy mục Tên Vật Tư trên menu Dữ Liệu Gốc và xem danh sách tên vật tư dùng chung toàn công ty (Danh Mục Vật Tư chọn tên từ đây).','2026-11-03 08:58:01','2026-11-16 07:44:08'),(257,1,116,'materData_material_view_departmentClassification','Xem Phân Loại','Thấy mục Phân Loại trên menu Dữ Liệu Gốc và xem bộ nhóm phân loại vật tư riêng của phòng ban đang chọn (ví dụ Vật tư HPLC, Dụng cụ vi sinh).','2026-11-03 08:58:01','2026-11-16 07:44:08'),(261,1,116,'materData_material_view_materialSignFlow','Xem Trình Ký Đề Nghị CP Vật Tư','Thấy mục Trình Ký Đề Nghị CP Vật Tư trên menu Dữ Liệu Gốc và xem bảng khai vai trò nào, cấp ký mấy, với điều kiện gì phải ký đề nghị cấp phát vật tư nội bộ của phòng đang chọn.','2026-11-03 08:58:01','2026-11-16 07:44:08'),(265,1,122,'materData_chemical_view_activeIngredient','Xem Đơn Chất','Thấy mục Đơn Chất trên menu Dữ Liệu Gốc và xem danh mục hoạt chất (tên IUPAC, CAS, công thức) kèm ngưỡng tồn trữ Phụ lục IV Bảng A và phân loại theo NĐ 24/2026.','2026-11-03 08:58:01','2026-11-16 07:44:08'),(277,1,122,'materData_chemical_view_chemName','Xem Hoá Chất','Thấy mục Hoá Chất trên menu Dữ Liệu Gốc và xem danh sách tên hoá chất (đơn chất hoặc hỗn hợp) với hoạt chất thành phần, % khối lượng, nhóm Bảng B và các phân loại khác (hoá chất cấm, hàng hoá đặc biệt).','2026-11-03 08:58:01','2026-11-16 07:44:08'),(283,1,128,'materData_standard_view_standardName','Xem Tên Chuẩn','Thấy mục Tên Chuẩn trên menu Dữ Liệu Gốc và xem danh sách tên chất chuẩn dùng trong kiểm nghiệm (tên, hoạt chất chính, số CAS).','2026-11-03 08:58:01','2026-11-16 07:44:08'),(289,1,128,'materData_standard_view_purpose','Xem Chỉ Tiêu Kiểm','Thấy mục Chỉ Tiêu Kiểm trên menu Dữ Liệu Gốc và xem danh sách chỉ tiêu kiểm nghiệm (ví dụ Định lượng, Tạp chất liên quan), dùng khi đề nghị, sử dụng chất chuẩn và lập gói theo sản phẩm.','2026-11-03 08:58:01','2026-11-16 07:44:08'),(293,1,134,'materData_common_view_company','Xem Công Ty','Thấy mục Công Ty trên menu Dữ Liệu Gốc và xem danh sách công ty dùng chung phần mềm. Mỗi công ty có bộ phòng ban riêng; ngưỡng PL IV cộng tồn trong phạm vi một công ty.','2026-11-03 08:58:01','2026-11-16 07:44:08'),(297,1,134,'materData_common_view_department','Xem Phòng Ban','Thấy mục Phòng Ban trên menu Dữ Liệu Gốc và xem các phòng ban của từng công ty (tên viết tắt, công ty trực thuộc, có phải bộ phận mua hàng không).','2026-11-03 08:58:01','2026-11-16 07:44:08'),(301,1,134,'materData_common_view_group','Xem Tổ','Thấy mục Tổ trên menu Dữ Liệu Gốc và xem các tổ bên trong phòng ban. Đang ở phòng ban nghiệp vụ thì chỉ thấy tổ của chính phòng đó; phòng ban chung thấy tổ của mọi phòng trong công ty.','2026-11-03 08:58:01','2026-11-16 07:44:08'),(305,1,134,'materData_common_view_unit','Xem Đơn Vị Tính','Thấy mục Đơn Vị Tính trên menu Dữ Liệu Gốc và xem các đơn vị (g, kg, ml, chai, hộp...) cùng nhóm đơn vị và hệ số quy đổi về đơn vị gốc.','2026-11-03 08:58:01','2026-11-16 07:44:08'),(311,1,134,'materData_common_view_packagingSpecification','Xem Quy Cách Đóng Gói','Thấy mục Quy Cách Đóng Gói trên menu Dữ Liệu Gốc và xem các quy cách dùng chung (ví dụ Chai thuỷ tinh 500 ml, Hộp 100 cái).','2026-11-03 08:58:01','2026-11-16 07:44:08'),(317,1,134,'materData_common_view_storageCondition','Xem Điều Kiện Bảo Quản','Thấy mục Điều Kiện Bảo Quản trên menu Dữ Liệu Gốc và xem các điều kiện bảo quản gắn vào danh mục hàng (ví dụ Tủ lạnh 2 - 8 °C, Tránh ánh sáng).','2026-11-03 08:58:01','2026-11-16 07:44:08'),(323,1,134,'materData_common_view_chemManufacturer','Xem Nhà Sản Xuất','Thấy mục Nhà Sản Xuất trên menu Dữ Liệu Gốc và xem danh sách hãng sản xuất (ví dụ Merck, Sigma-Aldrich) dùng khi khai danh mục và nhập hàng.','2026-11-03 08:58:01','2026-11-16 07:44:08'),(329,1,134,'materData_common_view_chemSupplier','Xem Nhà Cung Cấp','Thấy mục Nhà Cung Cấp trên menu Dữ Liệu Gốc và xem danh sách đơn vị cung cấp hàng (địa chỉ, mã số thuế, đầu mối liên hệ) dùng trên phiếu nhập.','2026-11-03 08:58:01','2026-11-16 07:44:08'),(339,1,134,'materData_common_view_productName','Xem Tên Sản Phẩm','Thấy mục Tên Sản Phẩm trên menu Dữ Liệu Gốc và xem danh sách sản phẩm của nhà máy, dùng khi đề nghị, sử dụng chất chuẩn / hoá chất và lập gói theo sản phẩm.','2026-11-03 08:58:01','2026-11-16 07:44:08'),(343,1,134,'materData_common_view_zone','Xem Định Khu','Thấy mục Định Khu trên menu Dữ Liệu Gốc và xem cấu trúc kho của phòng ban đang chọn (Kho/Phòng → Kệ/Tủ → Cột → Tầng → Vị Trí), ở cả chế độ Cấu trúc kho và Danh sách định khu.','2026-11-03 08:58:01','2026-11-16 07:44:08'),(347,1,134,'materData_common_view_consumptionObject','Xem Đối Tượng','Thấy mục Đối Tượng trên menu Dữ Liệu Gốc và xem danh sách đối tượng tiêu thụ vật tư (thường là thiết bị) theo từng tần suất, kể cả thiết bị đồng bộ từ phần mềm CAL.','2026-11-03 08:58:01','2026-11-16 07:44:08'),(351,1,NULL,'materData_material_manage','Thêm/Sửa/Khoá Dữ Liệu Gốc Vật Tư','Quyền nền cho các nút Thêm mới, Sửa, Khoá / Mở khoá ở các màn Dữ Liệu Gốc nhóm Vật Tư (Tên Vật Tư, Phân Loại, Trình Ký Đề Nghị CP Vật Tư).\nLưu ý: bật thêm quyền con \"Thêm/Sửa/Khoá <màn hình>\" cho từng màn được phép làm. Ở màn có bước duyệt, sửa bản ghi đã duyệt sẽ đưa bản ghi về Chờ duyệt.','2026-11-03 09:04:21','2026-11-03 11:35:42'),(352,1,NULL,'materData_material_review','Duyệt/Từ Chối Dữ Liệu Gốc Vật Tư','Quyền nền cho nút Duyệt / Từ chối bản ghi đang Chờ duyệt ở các màn Dữ Liệu Gốc nhóm Vật Tư có bước duyệt (Tên Vật Tư).\nLưu ý: bật thêm quyền con \"Duyệt/Từ Chối <màn hình>\". Bản ghi chỉ chọn được ở các màn nghiệp vụ sau khi Đã duyệt.','2026-11-03 09:04:21','2026-11-03 11:35:42'),(353,1,NULL,'materData_chemical_manage','Thêm/Sửa/Khoá Dữ Liệu Gốc Hoá Chất','Quyền nền cho các nút Thêm mới, Sửa, Khoá / Mở khoá ở các màn Dữ Liệu Gốc nhóm Hoá Chất (Đơn Chất, Nhóm Nguy Hại Bảng B, Hoá Chất).\nLưu ý: bật thêm quyền con \"Thêm/Sửa/Khoá <màn hình>\" cho từng màn được phép làm. Sửa bản ghi đã duyệt sẽ đưa bản ghi về Chờ duyệt.','2026-11-03 09:04:21','2026-11-03 11:35:42'),(354,1,NULL,'materData_chemical_review','Duyệt/Từ Chối Dữ Liệu Gốc Hoá Chất','Quyền nền cho nút Duyệt / Từ chối bản ghi đang Chờ duyệt ở các màn Dữ Liệu Gốc nhóm Hoá Chất (Đơn Chất, Nhóm Nguy Hại Bảng B, Hoá Chất).\nLưu ý: bật thêm quyền con \"Duyệt/Từ Chối <màn hình>\". Bản ghi chỉ chọn được ở các màn nghiệp vụ sau khi Đã duyệt.','2026-11-03 09:04:21','2026-11-03 11:35:42'),(355,1,NULL,'materData_standard_manage','Thêm/Sửa/Khoá Dữ Liệu Gốc Chất Chuẩn','Quyền nền cho các nút Thêm mới, Sửa, Khoá / Mở khoá ở các màn Dữ Liệu Gốc nhóm Chất Chuẩn (Tên Chuẩn, Chỉ Tiêu Kiểm).\nLưu ý: bật thêm quyền con \"Thêm/Sửa/Khoá <màn hình>\" cho từng màn được phép làm. Ở màn có bước duyệt, sửa bản ghi đã duyệt sẽ đưa bản ghi về Chờ duyệt.','2026-11-03 09:04:21','2026-11-03 11:35:42'),(356,1,NULL,'materData_standard_review','Duyệt/Từ Chối Dữ Liệu Gốc Chất Chuẩn','Quyền nền cho nút Duyệt / Từ chối bản ghi đang Chờ duyệt ở các màn Dữ Liệu Gốc nhóm Chất Chuẩn có bước duyệt (Tên Chuẩn).\nLưu ý: bật thêm quyền con \"Duyệt/Từ Chối <màn hình>\". Bản ghi chỉ chọn được ở các màn nghiệp vụ sau khi Đã duyệt.','2026-11-03 09:04:21','2026-11-03 11:35:42'),(357,1,NULL,'materData_common_manage','Thêm/Sửa/Khoá Dữ Liệu Gốc Dùng Chung','Quyền nền cho các nút Thêm mới, Sửa, Khoá / Mở khoá ở các màn Dữ Liệu Gốc dùng chung (Công Ty, Phòng Ban, Tổ, Đơn Vị Tính, Quy Cách Đóng Gói, Điều Kiện Bảo Quản, Nhà Sản Xuất, Nhà Cung Cấp, Trạng Thái, Tên Sản Phẩm, Định Khu, Đối Tượng).\nLưu ý: bật thêm quyền con \"Thêm/Sửa/Khoá <màn hình>\" cho từng màn được phép làm. Ở màn có bước duyệt, sửa bản ghi đã duyệt sẽ đưa bản ghi về Chờ duyệt.','2026-11-03 09:04:21','2026-11-03 11:35:42'),(358,1,NULL,'materData_common_review','Duyệt/Từ Chối Dữ Liệu Gốc Dùng Chung','Quyền nền cho nút Duyệt / Từ chối bản ghi đang Chờ duyệt ở các màn Dữ Liệu Gốc dùng chung có bước duyệt (Đơn Vị Tính, Quy Cách Đóng Gói, Điều Kiện Bảo Quản, Nhà Sản Xuất, Nhà Cung Cấp).\nLưu ý: bật thêm quyền con \"Duyệt/Từ Chối <màn hình>\". Bản ghi chỉ chọn được ở các màn nghiệp vụ sau khi Đã duyệt.','2026-11-03 09:04:21','2026-11-03 11:35:42'),(359,1,351,'materData_material_manage_materialName','Thêm/Sửa/Khoá Tên Vật Tư','Thêm tên vật tư mới, sửa tên, khoá / mở khoá ở màn Tên Vật Tư.\nLưu ý: tên mới hoặc tên vừa sửa ở trạng thái Chờ duyệt, phải được duyệt mới chọn được ở Danh Mục Vật Tư.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(360,1,352,'materData_material_review_materialName','Duyệt/Từ Chối Tên Vật Tư','Duyệt hoặc từ chối tên vật tư đang Chờ duyệt ở màn Tên Vật Tư. Tên chỉ chọn được ở Danh Mục Vật Tư sau khi Đã duyệt.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(361,1,351,'materData_material_manage_departmentClassification','Thêm/Sửa/Khoá Phân Loại','Thêm, đổi tên, khoá / mở khoá nhóm phân loại vật tư của phòng ban đang chọn ở màn Phân Loại. Không có bước duyệt.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(362,1,351,'materData_material_manage_materialSignFlow','Thêm/Sửa/Khoá Trình Ký Đề Nghị CP Vật Tư','Thêm, sửa, khoá / mở khoá dòng trình ký ở màn Trình Ký Đề Nghị CP Vật Tư của phòng đang chọn: vai trò nhận trình ký, cấp ký, người ký, nhóm điều kiện.\nLưu ý: bảng này quyết định đề nghị cấp phát vật tư lập sau đó phải qua những bước ký nào; không vai trò nào thoả điều kiện thì đề nghị được duyệt thẳng.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(363,1,353,'materData_chemical_manage_activeIngredient','Thêm/Sửa/Khoá Đơn Chất','Thêm, sửa, khoá / mở khoá hoạt chất ở màn Đơn Chất: tên, CAS, công thức, ngưỡng Bảng A, phân loại NĐ 24/2026, mục gộp hoạt chất.\nLưu ý: hoạt chất mới hoặc vừa sửa ở trạng thái Chờ duyệt, phải được duyệt mới ghép được vào tên hoá chất.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(364,1,354,'materData_chemical_review_activeIngredient','Duyệt/Từ Chối Đơn Chất','Duyệt hoặc từ chối hoạt chất đang Chờ duyệt ở màn Đơn Chất. Chỉ hoạt chất Đã duyệt mới ghép được vào tên hoá chất ở màn Hoá Chất.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(367,1,353,'materData_chemical_manage_chemName','Thêm/Sửa/Khoá Hoá Chất','Thêm, sửa, khoá / mở khoá tên hoá chất ở màn Hoá Chất: hoạt chất thành phần và % khối lượng, nhóm Bảng B, hỗn hợp có điều kiện, hoá chất cấm, hàng hoá đặc biệt.\nLưu ý: phân loại NĐ 24/2026 của danh mục hoá chất tự suy từ các thông tin này. Bản ghi vừa sửa phải được duyệt lại.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(368,1,354,'materData_chemical_review_chemName','Duyệt/Từ Chối Hoá Chất','Duyệt hoặc từ chối tên hoá chất đang Chờ duyệt ở màn Hoá Chất. Chỉ tên Đã duyệt mới chọn được khi khai Danh Mục Hoá Chất.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(369,1,355,'materData_standard_manage_standardName','Thêm/Sửa/Khoá Tên Chuẩn','Thêm, sửa, khoá / mở khoá tên chất chuẩn ở màn Tên Chuẩn (tên, hoạt chất chính, số CAS).\nLưu ý: tên mới hoặc tên vừa sửa ở trạng thái Chờ duyệt, phải được duyệt mới chọn được ở Danh Mục Chất Chuẩn.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(370,1,356,'materData_standard_review_standardName','Duyệt/Từ Chối Tên Chuẩn','Duyệt hoặc từ chối tên chuẩn đang Chờ duyệt ở màn Tên Chuẩn. Chỉ tên Đã duyệt mới chọn được khi khai Danh Mục Chất Chuẩn.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(371,1,355,'materData_standard_manage_purpose','Thêm/Sửa/Khoá Chỉ Tiêu Kiểm','Thêm, sửa, khoá / mở khoá chỉ tiêu kiểm nghiệm ở màn Chỉ Tiêu Kiểm. Không có bước duyệt.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(372,1,357,'materData_common_manage_company','Thêm/Sửa/Khoá Công Ty','Thêm, sửa, khoá / mở khoá công ty ở màn Công Ty (tên viết tắt, tên đầy đủ; mã CT00001... tự sinh). Không có bước duyệt.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(373,1,357,'materData_common_manage_department','Thêm/Sửa/Khoá Phòng Ban','Thêm, sửa, khoá / mở khoá phòng ban ở màn Phòng Ban: công ty trực thuộc, tên viết tắt, tên đầy đủ, đánh dấu bộ phận mua hàng (Cung Ứng / Hành Chánh).\nLưu ý: phòng được đánh dấu bộ phận mua hàng sẽ nhận và xử lý dự trù, đề nghị VPP của các phòng ban.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(374,1,357,'materData_common_manage_group','Thêm/Sửa/Khoá Tổ','Thêm, sửa, khoá / mở khoá tổ ở màn Tổ. Đang ở phòng ban nghiệp vụ thì chỉ làm được với tổ của chính phòng đó.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(375,1,357,'materData_common_manage_unit','Thêm/Sửa/Khoá Đơn Vị Tính','Thêm, sửa, khoá / mở khoá đơn vị tính ở màn Đơn Vị Tính (ký hiệu, tên, nhóm đơn vị, hệ số quy đổi).\nLưu ý: hệ số quy đổi dùng để cộng tồn và đối chiếu ngưỡng. Bản ghi vừa sửa phải được duyệt lại.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(376,1,358,'materData_common_review_unit','Duyệt/Từ Chối Đơn Vị Tính','Duyệt hoặc từ chối đơn vị tính đang Chờ duyệt ở màn Đơn Vị Tính. Chỉ đơn vị Đã duyệt mới chọn được ở các màn nghiệp vụ.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(377,1,357,'materData_common_manage_packagingSpecification','Thêm/Sửa/Khoá Quy Cách Đóng Gói','Thêm, sửa, khoá / mở khoá quy cách đóng gói ở màn Quy Cách Đóng Gói.\nLưu ý: bản ghi mới hoặc vừa sửa phải được duyệt mới chọn được khi khai danh mục và nhập hàng.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(378,1,358,'materData_common_review_packagingSpecification','Duyệt/Từ Chối Quy Cách Đóng Gói','Duyệt hoặc từ chối quy cách đóng gói đang Chờ duyệt. Chỉ quy cách Đã duyệt mới chọn được ở các màn nghiệp vụ.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(379,1,357,'materData_common_manage_storageCondition','Thêm/Sửa/Khoá Điều Kiện Bảo Quản','Thêm, sửa, khoá / mở khoá điều kiện bảo quản ở màn Điều Kiện Bảo Quản (tên điều kiện, ghi chú).\nLưu ý: bản ghi mới hoặc vừa sửa phải được duyệt mới chọn được khi khai danh mục.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(380,1,358,'materData_common_review_storageCondition','Duyệt/Từ Chối Điều Kiện Bảo Quản','Duyệt hoặc từ chối điều kiện bảo quản đang Chờ duyệt. Chỉ điều kiện Đã duyệt mới chọn được ở các màn nghiệp vụ.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(381,1,357,'materData_common_manage_chemManufacturer','Thêm/Sửa/Khoá Nhà Sản Xuất','Thêm, sửa, khoá / mở khoá nhà sản xuất ở màn Nhà Sản Xuất (tên viết tắt, tên đầy đủ).\nLưu ý: bản ghi mới hoặc vừa sửa phải được duyệt mới chọn được khi khai danh mục và nhập hàng.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(382,1,358,'materData_common_review_chemManufacturer','Duyệt/Từ Chối Nhà Sản Xuất','Duyệt hoặc từ chối nhà sản xuất đang Chờ duyệt. Chỉ nhà sản xuất Đã duyệt mới chọn được ở các màn nghiệp vụ.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(383,1,357,'materData_common_manage_chemSupplier','Thêm/Sửa/Khoá Nhà Cung Cấp','Thêm, sửa, khoá / mở khoá nhà cung cấp ở màn Nhà Cung Cấp (tên, địa chỉ, mã số thuế, ghi chú).\nLưu ý: bản ghi mới hoặc vừa sửa phải được duyệt mới chọn được trên phiếu nhập.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(384,1,358,'materData_common_review_chemSupplier','Duyệt/Từ Chối Nhà Cung Cấp','Duyệt hoặc từ chối nhà cung cấp đang Chờ duyệt. Chỉ nhà cung cấp Đã duyệt mới chọn được trên phiếu nhập.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(386,1,357,'materData_common_manage_productName','Thêm/Sửa/Khoá Tên Sản Phẩm','Thêm, sửa, khoá / mở khoá tên sản phẩm ở màn Tên Sản Phẩm. Không có bước duyệt.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(387,1,357,'materData_common_manage_zone','Thêm/Sửa/Khoá Định Khu','Khai và sửa cấu trúc kho của phòng ban đang chọn ở màn Định Khu: thêm, sửa, khoá kho / kệ / cột / tầng / vị trí, đổi phân loại vị trí (Dự Phòng, Sử Dụng, Biệt Trữ, Chờ Quyết Định, Loại Bỏ/Chờ Huỷ), thu nhỏ hoặc mở rộng lưới ở chế độ Cấu trúc kho.\nLưu ý: không khoá hay thu nhỏ được ô đang chứa lô hàng.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(388,1,357,'materData_common_manage_consumptionObject','Thêm/Sửa/Khoá Đối Tượng','Thêm, sửa, khoá / mở khoá đối tượng tiêu thụ vật tư ở màn Đối Tượng, và bấm Đồng bộ từ phần mềm CAL để lấy danh sách thiết bị, lịch bảo trì của khối B1, B2.','2026-11-03 09:04:21','2026-11-16 07:44:08'),(389,4,NULL,'export_chemical_update','Điều Chỉnh Sổ Sử Dụng Hoá Chất','Sửa (lô, số lượng, người kiểm tra, số PKN / OOS / BCSL, mục đích) hoặc khoá / mở khoá một dòng ở tab Sổ sử dụng hoá chất, kể cả phiếu ngày cũ. Khoá thì số lượng được cộng trả lại tồn, mở khoá thì trừ lại; mỗi lần sửa được lưu lịch sử điều chỉnh.\nLưu ý: dòng sinh từ phiếu cách ly chỉ xử lý ở tab Cách ly - Loại bỏ - Huỷ; dòng chuyển cho phòng khác không sửa được; dòng trả về kho chỉ huỷ ở tab Trả hoá chất Acetonitril hoặc Methanol về kho, phiếu sử dụng đã có lượng trả không khoá / đổi lô được và không sửa số lượng nhỏ hơn lượng đã trả.','2026-11-03 12:44:54','2026-11-14 15:44:54'),(390,4,NULL,'export_standard_update','Điều Chỉnh Sổ Sử Dụng Chất Chuẩn','Sửa (ống chuẩn, Tổ, số lượng, sản phẩm, số lô, chỉ tiêu) một dòng ở tab Sổ sử dụng chất chuẩn, kể cả phiếu ngày cũ. Mỗi lần sửa được lưu lịch sử điều chỉnh.\nLưu ý: dòng sinh từ phiếu cách ly chỉ xử lý ở tab Cách ly - Loại bỏ - Huỷ; dòng cấp phát liên phòng ban không sửa được; loại phiếu không đổi được.','2026-11-09 09:17:41','2026-11-09 09:17:41'),(391,5,NULL,'inventory_chemical_location','Định Khu Nhanh Hoá Chất','Xếp vị trí lưu trữ cho mã xuất nhập còn tồn mà chưa có định khu, ngay ở khối \"Chưa xếp vị trí\" của tab Theo định khu (Tồn Kho Hoá Chất): từng mã hoặc nhiều mã đã chọn vào cùng một vị trí. Mỗi mã được ghi lịch sử phiếu nhập và Audit Trail.\nLưu ý: chỉ chọn được vị trí Dự Phòng / Sử Dụng / chưa phân loại; vị trí cùng kệ/tủ với hoá chất tương kỵ (Sơ đồ lưu trữ GHS) bị khoá. Mã đã có định khu muốn đổi chỗ thì Điều chỉnh phiếu nhập (ghi lý do).','2026-11-09 12:44:45','2026-11-09 12:44:45'),(392,5,41,'inventory_material_tab_expiring','Tab Cận hạn dùng','Xem tab Cận hạn dùng: các lô có hạn rơi vào 6 tháng tới hoặc đã quá hạn, lọc nhanh theo mốc ≤ 3 tháng / 1 tháng / 2 tuần / 1 tuần.','2026-11-10 17:37:47','2026-11-10 17:37:47'),(393,5,NULL,'inventory_material_location','Định Khu Vật Tư','Xếp vị trí lưu trữ cho mã xuất nhập vật tư còn tồn ở tab Tồn kho theo vị trí (Tồn Kho Vật Tư): Định khu mã \"Chưa xếp vị trí\", Thêm vật tư vào một ô, Đổi vị trí mã đã có định khu (bắt buộc lý do) và kéo thả giữa các ô. Mỗi mã được ghi lịch sử phiếu nhập và Audit Trail.\nLưu ý: chỉ chọn được vị trí Dự Phòng / Sử Dụng / chưa phân loại; hàng ở khu Biệt Trữ / Cách Ly / Loại Bỏ xử lý theo luồng Cách ly.','2026-11-10 19:15:56','2026-11-10 19:15:56'),(394,2,NULL,'category_vpp_view','Xem Danh Mục VPP Chung','Thấy mục Danh Mục › VPP trên menu và mở màn hình.\nLưu ý: từng tab bên trong (Danh mục VPP công ty, VPP của phòng, 3 tab danh sách theo chu kỳ) cần thêm quyền xem tab tương ứng.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(395,2,NULL,'category_vpp_create','Thêm Danh Mục VPP Chung','Thêm mã VPP mới vào Danh mục VPP công ty: chọn tên VPP và nhà sản xuất, khai thông tin kỹ thuật, Part Number, 4 tiêu chí phân loại, bộ phận mua hàng, thời gian đặt hàng.\nLưu ý: mã M00001... tự sinh. Mã mới ở trạng thái Chờ duyệt, các phòng chỉ dùng được sau khi được duyệt.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(396,2,NULL,'category_vpp_update','Sửa Danh Mục VPP Chung','Sửa thông tin mã VPP trong Danh mục VPP công ty (nút Sửa trên dòng). Mỗi lần sửa được lưu vào lịch sử thay đổi của mã.\nLưu ý: sửa xong mã quay về Chờ duyệt và phải được duyệt lại. Thời gian đặt hàng không sửa ở đây mà dùng quyền Điều Chỉnh Thời Gian Đặt Hàng.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(397,2,NULL,'category_vpp_deActive','Vô Hiệu Danh Mục VPP Chung','Khoá hoặc mở khoá mã VPP trong Danh mục VPP công ty (bắt buộc ghi lý do). Mã bị khoá không còn xuất hiện khi chọn VPP ở các màn nghiệp vụ.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(398,3,NULL,'import_vpp_view','Xem Phiếu Nhập VPP','Thấy mục Nhập › VPP trên menu và mở màn hình.\nLưu ý: tab Sổ nhập VPP và Chờ kiểm tra cần thêm quyền xem tab tương ứng.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(399,3,NULL,'import_vpp_create','Thêm Phiếu Nhập VPP','Lập phiếu nhập kho VPP cho phòng đang chọn: chọn VPP của phòng, số lượng, số lần nhập (mỗi lô một mã xuất nhập, tối đa 50), thông tin chứng từ, định khu tạm trong khu Biệt Trữ, file đính kèm.\nLưu ý: lô mới ở trạng thái Chờ kiểm tra, chưa cộng vào tồn cho tới khi kiểm tra Đạt.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(400,3,NULL,'import_vpp_update','Sửa Phiếu Nhập VPP','Điều chỉnh thông tin phiếu nhập VPP (mỗi lần sửa lưu lịch sử) và Xác nhận kiểm tra lô ở tab Chờ kiểm tra: Đạt thì lô vào tồn và chuyển về định khu thật; Không đạt thì trả hàng, lô không vào tồn.\nLưu ý: kết quả kiểm tra là quyết định cuối, không kiểm tra lại được.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(401,4,NULL,'export_vpp_view','Xem Sử Dụng VPP','Thấy mục Đề Nghị - Sử Dụng › VPP trên menu và mở màn hình.\nLưu ý: từng tab bên trong cần thêm quyền xem tab tương ứng.','2026-11-11 16:13:57','2026-11-12 13:37:58'),(402,4,NULL,'export_vpp_request','Tạo Đề Nghị VPP Liên Phòng Ban / Đến HC','Lập, sửa và gửi đề nghị xin VPP từ phòng khác (tab Phòng ban khác) hoặc từ kho VPP Hành Chính (tab VPP đến HC); sửa và gửi lại phiếu đang Lưu tạm hoặc Bị từ chối.\nLưu ý: gồm cả gửi đề nghị từ danh sách VPP cần đề nghị Hành Chính. Phiếu gửi đi qua các bước ký theo Trình Ký Liên Phòng Ban VPP.','2026-11-11 16:13:57','2026-11-12 13:37:58'),(404,4,NULL,'export_vpp_issue','Sử Dụng VPP','Ghi phiếu Sử dụng VPP ở tab Sử Dụng VPP (quét mã hoặc chọn lô từ tồn kho): lưu là trừ tồn ngay, không qua đề nghị / ký duyệt, không có Phiếu Tạm.\nLưu ý: số lượng không vượt tồn còn của lô + 5%; lô hết hạn không chọn được.','2026-11-11 16:13:57','2026-11-12 13:37:58'),(405,5,NULL,'inventory_vpp_view','Xem Tồn Kho VPP','Thấy mục Tồn Kho › VPP trên menu và xem tồn của phòng đang chọn. Tồn tính tự động từ nhập, cân đối, cấp phát; không có chỗ nhập tồn bằng tay.\nLưu ý: từng tab bên trong cần thêm quyền xem tab tương ứng.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(406,6,NULL,'estimate_vpp_view','Xem Dự Trù VPP','Thấy mục Dự Trù › VPP trên menu và mở màn hình (phiếu dự trù đề nghị bộ phận mua hàng mua VPP).\nLưu ý: từng tab bên trong cần thêm quyền xem tab tương ứng.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(407,6,NULL,'estimate_vpp_create','Lập Dự Trù VPP','Lập phiếu dự trù VPP mới (chọn tháng / năm dự trù, ghi chú), kể cả lập nhanh bằng cách tick chọn ở Danh sách VPP cần dự trù. Phiếu mới ở trạng thái Nháp.\nLưu ý: chỉ phòng Hành Chánh (phòng giữ kho VPP) lập được dự trù VPP - đang chọn phòng khác thì nút Lập phiếu dự trù bị khoá.','2026-11-11 16:13:57','2026-11-14 16:52:26'),(408,6,NULL,'estimate_vpp_update','Sửa Dự Trù VPP','Sửa phiếu dự trù VPP đang Nháp hoặc Bị từ chối: đổi tháng, ghi chú, thêm / sửa / bỏ mặt hàng, số lượng từng tháng, file đính kèm; rồi bấm Trình ký để gửi đi ký duyệt.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(409,6,NULL,'estimate_vpp_sign','Ký Duyệt Dự Trù VPP','Ký đồng ý hoặc từ chối phiếu dự trù VPP khi tới bước của mình (nhập lại mật khẩu). Bước 1: Quản Lý Bộ Phận của phòng lập phiếu; bước 2: Ban Giám Đốc.\nLưu ý: người ký còn được xác định theo vai trò và phạm vi phòng ban, không chỉ dựa vào quyền này. Phiếu chờ ký hiện ở Trang chủ.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(410,2,NULL,'category_vpp_approve','Duyệt Danh Mục VPP Chung','Duyệt mã VPP đang Chờ duyệt trong Danh mục VPP công ty (nhập lại mật khẩu khi duyệt). Mã chờ duyệt hiện ở Trang chủ của người có quyền này.\nLưu ý: chỉ mã Đã duyệt mới được các phòng khai vào VPP của phòng và dùng ở Nhập, Đề nghị, Dự trù.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(411,2,NULL,'category_vpp_dept_manage','Quản lý danh mục VPP phòng','Thêm, sửa, khoá VPP ở tab VPP của phòng (phòng đang chọn): đơn vị tính của phòng, phân loại của phòng, ngưỡng tồn tối thiểu / tối đa, định khu dự kiến.\nLưu ý: chỉ VPP đã khai ở tab này mới nhập kho và đề nghị nội bộ được ở phòng. Tồn dưới ngưỡng tối thiểu thì VPP tự vào Danh sách cần dự trù.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(412,3,NULL,'import_vpp_label','In Nhãn VPP','In nhãn lô VPP (có mã QR, mục đích sử dụng) từ nút In nhãn trên Sổ nhập VPP, để dán lên hàng.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(413,5,NULL,'inventory_vpp_balancing','Cân Đối Tồn Kho VPP','Bấm Cân đối trên lô ở tab Theo mã xuất nhập để điều chỉnh tồn sổ sách cho khớp thực tế (nhập số + hoặc −, kèm lý do), khi có sai số cân, hao hụt hoặc đếm nhầm.\nLưu ý: tổng cân đối của một lô không vượt quá 5% lượng nhập và tồn không được âm.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(414,5,NULL,'inventory_vpp_stocktake','Kiểm Kê Kho VPP','Kiểm kê kho VPP theo quý ở tab Kiểm kê định kỳ: mở phiếu (hệ thống chụp tồn sổ sách), nhập số thực đếm (quét QR trên nhãn), chốt phiếu để hệ thống tự cân đối phần lệch; huỷ phiếu đang đếm để mở lại.\nLưu ý: mỗi phòng mỗi quý chỉ mở một phiếu. Dòng lệch vượt giới hạn cân đối được đánh dấu Chờ Xử Lý thay vì tự cân đối.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(415,6,NULL,'estimate_vpp_delete','Huỷ Phiếu Dự Trù VPP','Huỷ phiếu dự trù VPP khi phiếu còn Nháp hoặc Bị từ chối (chưa trình ký).','2026-11-11 16:13:57','2026-11-11 16:13:57'),(416,6,NULL,'estimate_vpp_tracking','Theo Dõi Giao Hàng Dự Trù VPP','Phía phòng đề nghị theo dõi mặt hàng dự trù đã duyệt: đánh dấu Hoàn thành khi đã nhận đủ hàng, đề nghị Huỷ mặt hàng không cần nữa, hoặc hoàn tác.\nLưu ý: huỷ một mặt hàng cần cả bộ phận mua hàng đồng ý.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(417,1,NULL,'materData_vpp_view','Xem Dữ Liệu Gốc VPP','Quyền nền để xem các màn Dữ Liệu Gốc nhóm VPP: Tên VPP. Chỉ xem, không thêm hay sửa được.\nLưu ý: chọn màn nào hiện trên menu bằng các quyền con \"Xem <màn hình>\" bên dưới; chỉ có quyền này mà không có quyền con thì không thấy màn nào.','2026-11-11 16:13:57','2026-11-16 07:44:08'),(418,3,NULL,'import_vpp_attachment_status','Đổi Trạng Thái File Đính Kèm VPP','Đổi trạng thái file đính kèm của phiếu nhập VPP giữa Đang sử dụng và Ngưng sử dụng. File không bị xoá, vẫn xem lại được.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(419,4,NULL,'export_vpp_transfer','Cấp Phát VPP Liên Phòng Ban','Phòng đang giữ hàng cấp phát đề nghị liên phòng ban và đề nghị VPP do phòng khác gửi tới: chọn mã xuất nhập (lô) của phòng mình và số lượng rồi Cấp phát (trừ tồn ngay), hoặc Từ chối cấp từng mục.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(420,4,NULL,'export_vpp_transfer_receive','Nhận Chuyển VPP Liên Phòng Ban','Phòng đề nghị nhận VPP mà phòng khác đã cấp: bấm Nhận, ghi kết luận kiểm tra và chọn định khu thật (bắt buộc). Lô vào tồn của phòng nhận ngay, mã lô giữ mã gốc kèm hậu tố -CK1, -CK2... để truy vết.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(421,4,NULL,'export_vpp_transfer_return','Từ Chối Nhận Chuyển VPP','Phòng đề nghị từ chối nhận VPP đã được cấp (ví dụ hàng không đạt khi kiểm tra). Số lượng tự hoàn lại tồn cho phòng đã cấp.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(422,3,NULL,'import_vpp_attachment_upload','Đính Kèm Thêm File VPP','Tải thêm file hồ sơ (hoá đơn, phiếu giao hàng, chứng nhận...) vào phiếu nhập VPP đã lập.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(423,2,NULL,'category_vpp_periodic_manage','Quản Lý Đề Nghị VPP Theo Chu Kỳ','Lập và quản lý 3 loại danh sách VPP theo chu kỳ ở Danh Mục › VPP (đề nghị nội bộ, đề nghị liên phòng ban, dự trù): thêm, sửa, khoá danh sách, đặt lịch (hằng tuần / tháng / quý hoặc mỗi N ngày, ngày bắt đầu) và tạo phiếu ngay từ danh sách.\nLưu ý: đến hạn, hệ thống tự tạo phiếu ở trạng thái Lưu tạm / Nháp để người lập kiểm tra rồi gửi đi.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(424,4,NULL,'export_vpp_quarantine','Cách Ly / Huỷ VPP Hỏng','Bước 1 và 3 của quy trình VPP hỏng ở tab Cách ly - Loại bỏ - Huỷ: lập phiếu Cách ly (chọn mã xuất nhập, số lượng, định khu Chờ Quyết Định, lý do; hàng bị trừ tồn ngay) và ghi nhận Huỷ khi đã tiêu huỷ thực tế (ghi phương pháp, nhập lại mật khẩu).','2026-11-11 16:13:57','2026-11-11 16:13:57'),(425,4,NULL,'export_vpp_quarantine_decide','Quyết Định Loại Bỏ VPP Hỏng','Bước 2 của quy trình VPP hỏng: với VPP đang cách ly, quyết định Loại bỏ (chuyển sang định khu Loại Bỏ/Chờ Huỷ, không quay lại kho được) hoặc Trả về kho (cộng lại tồn); ghi căn cứ và nhập lại mật khẩu.\nLưu ý: phiếu cách ly chờ quyết định hiện ở Trang chủ của người có quyền này.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(426,4,NULL,'export_vpp_issue_lot_adjust','Điều Chỉnh Mã Xuất Nhập Khi Cấp Phát VPP Liên Phòng Ban','Khi cấp phát đề nghị VPP liên phòng ban / đến HC, được đổi hoặc thêm mã xuất nhập khác với lô hệ thống đề xuất (FEFO/FIFO).','2026-11-11 16:13:57','2026-11-12 13:37:58'),(427,4,NULL,'export_vpp_update','Điều Chỉnh Sổ Sử Dụng VPP','Sửa hoặc khoá một dòng ghi sai ở tab Sổ cấp phát (số lượng, mục đích, ghi chú). Mỗi lần điều chỉnh được lưu lịch sử.\nLưu ý: dòng sinh từ phiếu cách ly chỉ xử lý ở tab Cách ly - Loại bỏ - Huỷ; dòng cấp phát liên phòng ban không sửa được.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(428,4,NULL,'export_vpp_issue_amount_adjust','Điều Chỉnh Số Lượng Khi Cấp Phát VPP Liên Phòng Ban','Khi cấp phát đề nghị VPP liên phòng ban / đến HC, được sửa số lượng cấp khác số hệ thống đề xuất (cấp một phần / cấp vượt).','2026-11-11 16:13:57','2026-11-12 13:37:58'),(429,6,NULL,'estimate_vpp_purchasing','Tiếp Nhận Xử Lý Dự Trù VPP','Tiếp nhận xử lý dự trù VPP của phòng Hành Chánh: xem tab Đơn dự trù đã được phê duyệt, bấm Tiếp nhận phiếu, cập nhật Ngày hẹn đáp ứng cho từng tháng của từng VPP.\nLưu ý: chỉ có tác dụng khi đang chọn phòng Hành Chánh ở thanh trên cùng. Phòng Hành Chánh vừa lập vừa tiếp nhận nên huỷ mặt hàng chỉ cần một lần xác nhận. Phiếu chờ tiếp nhận hiện ở Trang chủ.','2026-11-11 16:13:57','2026-11-14 16:52:26'),(430,6,406,'estimate_vpp_tab_list','Tab Danh Sách Phiếu','Xem tab Danh sách phiếu: các phiếu dự trù VPP của phòng đang chọn và trạng thái ký.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(431,6,406,'estimate_vpp_tab_tracking','Tab Theo Dõi Dự Trù','Xem tab Theo dõi dự trù: từng mặt hàng đã duyệt của phòng với ngày mong muốn, ngày hẹn đáp ứng, trạng thái và cột Trao đổi.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(432,6,406,'estimate_vpp_tab_watchlist','Tab Danh Sách VPP Cần Dự Trù','Xem tab Danh sách VPP cần dự trù: VPP dưới ngưỡng tồn tối thiểu, do người dùng đề nghị, hoặc thiếu ở Khả dụng tháng tới; tick chọn để lập phiếu dự trù nhanh.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(433,6,406,'estimate_vpp_tab_approved','Tab Đơn Dự Trù Đã Được Phê Duyệt','Xem tab Đơn dự trù đã được phê duyệt: phiếu dự trù VPP đã duyệt của phòng Hành Chánh chờ tiếp nhận và hẹn ngày đáp ứng.\nLưu ý: tab chỉ hiện khi đang chọn phòng Hành Chánh và có thêm quyền Tiếp Nhận Xử Lý Dự Trù VPP.','2026-11-11 16:13:57','2026-11-14 16:52:26'),(434,2,394,'category_vpp_tab_company','Tab Danh mục VPP công ty','Xem tab Danh mục VPP công ty: toàn bộ mã VPP dùng chung công ty với phân loại, bộ phận mua hàng, thời gian đặt hàng, trạng thái duyệt và lịch sử thay đổi.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(435,2,394,'category_vpp_tab_department','Tab VPP của phòng','Xem tab VPP của phòng: các VPP phòng đang chọn đã khai, kèm đơn vị tính, phân loại của phòng, ngưỡng tồn, định khu.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(437,2,394,'category_vpp_tab_external','Tab DS đề nghị liên phòng ban theo chu kỳ','Xem tab DS đề nghị liên phòng ban theo chu kỳ: các danh sách tự tạo đề nghị gửi phòng ban khác (kể cả VPP đến Hành Chánh) theo lịch.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(438,2,394,'category_vpp_tab_estimate','Tab DS dự trù theo chu kỳ','Xem tab DS dự trù theo chu kỳ: các danh sách tự lập phiếu dự trù Nháp theo lịch, cho tháng tạo phiếu hoặc 1 - 3 tháng sau.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(439,3,398,'import_vpp_tab_book','Tab Sổ nhập VPP','Xem tab Sổ nhập VPP: mọi lô VPP đã nhập của phòng với tình trạng kiểm tra; nơi lập phiếu nhập, điều chỉnh, in nhãn, xem file đính kèm.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(440,3,398,'import_vpp_tab_check','Tab Chờ kiểm tra','Xem tab Chờ kiểm tra: các lô VPP vừa nhập, đang nằm trong khu Biệt Trữ chờ xác nhận kiểm tra.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(444,4,401,'export_vpp_tab_vpp','Tab Đề nghị liên phòng ban - VPP đến HC','Xem tab Đề nghị liên phòng ban - VPP đến HC: các đề nghị xin văn phòng phẩm từ kho của Hành Chánh và danh sách VPP cần đề nghị Hành Chính.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(445,4,401,'export_vpp_tab_transfer','Tab Đề nghị liên phòng ban - Phòng ban khác','Xem tab Đề nghị liên phòng ban - Phòng ban khác: đề nghị phòng mình gửi đi xin VPP và đề nghị phòng khác gửi tới phòng mình.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(447,4,401,'export_vpp_tab_book','Tab Sổ sử dụng VPP','Xem tab Sổ sử dụng VPP: nhật ký mọi lần VPP rời kho của phòng (sử dụng, loại bỏ, chuyển cho phòng khác).','2026-11-11 16:13:57','2026-11-12 13:37:58'),(448,4,401,'export_vpp_tab_quarantine','Tab Cách ly - Loại bỏ - Huỷ','Xem tab Cách ly - Loại bỏ - Huỷ: các phiếu cách ly VPP hỏng theo từng bước (chờ quyết định, loại bỏ - chờ huỷ, đã huỷ, trả về kho).','2026-11-11 16:13:57','2026-11-11 16:13:57'),(450,5,405,'inventory_vpp_tab_code','Tab Theo mã xuất nhập','Xem tab Theo mã xuất nhập: tồn từng lô theo kỳ (đầu kỳ, nhập, sử dụng, cách ly / huỷ, cuối kỳ), hạn dùng, vị trí; nơi có nút Cân đối và Biểu đồ.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(451,5,405,'inventory_vpp_tab_vpp','Tab Tồn theo mã VPP','Xem tab Tồn theo mã VPP: tổng tồn gộp các lô theo VPP, hạn gần nhất, nhà sản xuất; lọc theo phân loại VPP.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(452,5,405,'inventory_vpp_tab_zone','Tab Tồn kho theo vị trí','Xem tab Tồn kho theo vị trí: sơ đồ kho - kệ - vị trí, bấm vào vị trí để xem lô đang để ở đó.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(453,5,405,'inventory_vpp_tab_next','Tab Khả dụng tháng tới','Xem tab Khả dụng tháng tới: tồn hiện có có đủ cho nhu cầu theo chu kỳ của tháng tới không, thiếu bao nhiêu, lượng nên dự trù.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(454,5,405,'inventory_vpp_tab_check','Tab Kiểm kê định kỳ','Xem tab Kiểm kê định kỳ: phiếu kiểm kê theo quý của phòng, số thực đếm và chênh lệch.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(455,6,431,'estimate_vpp_chat','Trao Đổi Theo Dõi Dự Trù','Gửi tin nhắn trao đổi giữa phòng đề nghị và bộ phận mua hàng ở cột Trao đổi của từng VPP trong tab Theo dõi dự trù.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(459,1,NULL,'materData_vppTransferSign_view','Xem Trình Ký Liên Phòng Ban VPP','Thấy mục Trình Ký Đề Nghị Liên Phòng Ban VPP trên menu Dữ Liệu Gốc và xem các bước ký mà đề nghị chuyển VPP giữa các phòng ban và đề nghị VPP đến Hành Chánh phải đi qua (khai riêng theo loại đề nghị và công ty). Chỉ xem.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(460,1,NULL,'materData_vppTransferSign_create','Thêm Bước Ký Liên Phòng Ban VPP','Thêm bước ký mới ở màn Trình Ký Đề Nghị Liên Phòng Ban VPP: loại đề nghị (VPP đến HC hoặc liên phòng ban khác), công ty của phòng đề nghị, thứ tự bước, vai trò ký và phạm vi phòng ban của người ký.\nLưu ý: công ty chưa khai bước ký nào thì đề nghị đi thẳng tới phòng được đề nghị, không qua bước ký.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(461,1,NULL,'materData_vppTransferSign_update','Sửa Bước Ký Liên Phòng Ban VPP','Sửa bước ký đã khai ở màn Trình Ký Đề Nghị Liên Phòng Ban VPP (đổi thứ tự bước, vai trò ký, phạm vi phòng ban...).','2026-11-11 16:13:57','2026-11-11 16:13:57'),(462,1,NULL,'materData_vppTransferSign_deActive','Khoá Bước Ký Liên Phòng Ban VPP','Khoá bước ký ở màn Trình Ký Đề Nghị Liên Phòng Ban VPP để ngừng áp dụng, hoặc mở khoá để dùng lại. Bước ký không bị xoá hẳn.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(464,1,NULL,'materData_vpp_manage','Thêm/Sửa/Khoá Dữ Liệu Gốc VPP','Quyền nền cho các nút Thêm mới, Sửa, Khoá / Mở khoá ở các màn Dữ Liệu Gốc nhóm VPP (Tên VPP).\nLưu ý: bật thêm quyền con \"Thêm/Sửa/Khoá <màn hình>\" cho từng màn được phép làm. Sửa bản ghi đã duyệt sẽ đưa bản ghi về Chờ duyệt.','2026-11-11 16:13:57','2026-11-16 07:44:08'),(466,5,405,'inventory_vpp_tab_expiring','Tab Cận hạn dùng','Xem tab Cận hạn dùng: các lô có hạn rơi vào 6 tháng tới hoặc đã quá hạn, lọc nhanh theo mốc ≤ 3 tháng / 1 tháng / 2 tuần / 1 tuần.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(467,5,NULL,'inventory_vpp_location','Định Khu VPP','Xếp vị trí lưu trữ cho mã xuất nhập VPP còn tồn ở tab Tồn kho theo vị trí (Tồn Kho VPP): Định khu mã \"Chưa xếp vị trí\", Thêm VPP vào một ô, Đổi vị trí mã đã có định khu (bắt buộc lý do) và kéo thả giữa các ô. Mỗi mã được ghi lịch sử phiếu nhập và Audit Trail.\nLưu ý: chỉ chọn được vị trí Dự Phòng / Sử Dụng / chưa phân loại; hàng ở khu Biệt Trữ / Cách Ly / Loại Bỏ xử lý theo luồng Cách ly.','2026-11-11 16:13:57','2026-11-11 16:13:57'),(468,4,401,'export_vpp_tab_use','Tab Sử Dụng VPP','Xem tab Sử Dụng VPP: nơi bấm Sử dụng VPP để ghi phiếu (quét mã hoặc chọn lô từ tồn kho của phòng).\nLưu ý: ghi phiếu cần thêm quyền Sử Dụng VPP.','2026-11-12 13:37:58','2026-11-12 13:37:58'),(469,4,NULL,'export_material_label','In Nhãn Cấp Phát Vật Tư','In nhãn cấp phát (tên vật tư, ngày cấp, hạn dùng, số lượng, người đề nghị, mục đích, QR mã xuất nhập) cho một dòng ở tab Sổ cấp phát. Mỗi lần in được ghi Audit Trail.\nCũng in được nhãn Cách ly - Chờ quyết định và Loại bỏ - Chờ huỷ cho dòng sinh từ phiếu cách ly.\nLưu ý: phiếu cách ly đã huỷ / trả về kho, dòng loại bỏ lập thẳng và cấp phát liên phòng ban không có nhãn.','2026-11-13 16:22:45','2026-11-13 16:22:45'),(472,4,NULL,'export_chemical_return','Trả Hoá Chất Acetonitril / Methanol Về Kho','Khai báo trả lại tồn một lượng Acetonitril hoặc Methanol đã ghi sử dụng (tab Trả hoá chất Acetonitril hoặc Methanol về kho): lượng trả cộng lại đúng lô đã lấy ra, và huỷ phiếu trả đã khai.\nLưu ý: tổng lượng trả của một phiếu sử dụng không vượt số lượng đã sử dụng; huỷ phiếu trả chỉ được khi lô còn đủ tồn để trừ lại.','2026-11-14 15:44:54','2026-11-14 15:44:54'),(473,4,33,'export_chemical_tab_return','Tab Trả hoá chất Acetonitril hoặc Methanol về kho','Xem tab Trả hoá chất Acetonitril hoặc Methanol về kho: các phiếu sử dụng Acetonitril / Methanol còn trả được và lịch sử các lần trả về kho.','2026-11-14 15:44:54','2026-11-14 15:44:54'),(474,1,NULL,'materData_vpp_review','Duyệt/Từ Chối Dữ Liệu Gốc VPP','Quyền nền cho nút Duyệt / Từ chối bản ghi đang Chờ duyệt ở các màn Dữ Liệu Gốc nhóm VPP có bước duyệt (Tên VPP).\nLưu ý: bật thêm quyền con \"Duyệt/Từ Chối <màn hình>\". Bản ghi chỉ chọn được ở các màn nghiệp vụ sau khi Đã duyệt.','2026-11-16 07:44:08','2026-11-16 07:44:08'),(475,1,417,'materData_vpp_view_vppName','Xem Tên VPP','Thấy mục Tên VPP trên menu Dữ Liệu Gốc và xem danh sách tên văn phòng phẩm dùng chung toàn công ty (Danh Mục VPP chọn tên từ đây).','2026-11-16 07:44:08','2026-11-16 07:44:08'),(476,1,464,'materData_vpp_manage_vppName','Thêm/Sửa/Khoá Tên VPP','Thêm tên VPP mới, sửa tên, khoá / mở khoá ở màn Tên VPP.\nLưu ý: tên mới hoặc tên vừa sửa ở trạng thái Chờ duyệt, phải được duyệt mới chọn được ở Danh Mục VPP.','2026-11-16 07:44:08','2026-11-16 07:44:08'),(477,1,474,'materData_vpp_review_vppName','Duyệt/Từ Chối Tên VPP','Duyệt hoặc từ chối tên VPP đang Chờ duyệt ở màn Tên VPP. Tên chỉ chọn được ở Danh Mục VPP sau khi Đã duyệt.','2026-11-16 07:44:08','2026-11-16 07:44:08');
INSERT INTO `roles` (`id`, `name`, `description`, `kinds`, `created_at`, `updated_at`) VALUES (1,'Admin','Quản lý hệ thống','material,vpp,chemical,standard','2026-08-28 15:24:49','2026-08-28 15:24:49'),(4,'Quan lý Kho Vật Tư','Nhân Viên Quản Lý Kho Vật Tư','material','2026-09-06 10:26:18','2026-09-06 10:26:18'),(5,'Quản Lý Kho Hóa Chất','Nhân Viên Quản Lý Kho Hóa Chất','chemical','2026-09-06 10:26:41','2026-09-06 10:26:41'),(6,'Quản Lý Kho Chất Chuẩn','Nhân Viên Quản Lý Kho Chất Chuẩn','standard','2026-09-06 10:27:05','2026-11-03 09:45:29'),(7,'Quản Lý Bộ Phân','Phó/Trường Các Phòng Ban','material,vpp,chemical,standard','2026-09-06 10:27:56','2026-09-06 10:27:56'),(8,'Người Đề nghị vật tư','Người thực hiện các đề cấp phát nghị vật tư','material','2026-09-06 10:28:48','2026-09-06 13:44:44'),(21,'Người dùng Hoá chất','Nhân Viên Các Bộ Phận Có Thể Sử Dụng Vật Tư/Hóa Chất/Chất Chuẩn','chemical','2026-09-06 10:44:27','2026-10-19 15:21:17'),(22,'Người Xem','Người Thuộc công ty có thể xem toàn bộ dữ liệu trên hệ thống nhưng không thể thao tác','material,vpp,chemical,standard','2026-09-06 10:45:57','2026-09-06 10:45:57'),(23,'Nhóm CSV','Nhóm quản lý hệ thống máy tính phòng QA','material,vpp,chemical,standard','2026-09-06 10:47:37','2026-09-06 10:47:37'),(24,'Người Đề nghị chuẩn','Người đề nghị cấp phát chuẩn','standard','2026-09-06 13:43:44','2026-09-06 13:45:02'),(25,'Ban Giám Đốc','Ban Giám Đốc','material,vpp,chemical,standard','2026-09-08 15:00:29','2026-09-08 15:11:44'),(26,'Tổ Tưởng Quản Lý Kho Vật Tư','Tổ Tưởng - Quản Lý Kho Vật Tư','material','2026-09-16 10:35:31','2026-09-16 10:35:31'),(28,'Tổ Tưởng Quản Lý Kho Hoá chất - Chất chuẩn','Tổ Tưởng Quản Lý Kho Hoá chất - Chất chuẩn','chemical,standard','2026-09-16 10:36:32','2026-11-03 09:49:42'),(29,'Nhân Viên Cung Ứng Vật Tư','Bộ phận mua hàng: tiếp nhận, theo dõi giao hàng, hẹn ngày đáp ứng và xử lý huỷ mục các phiếu dự trù đã duyệt','material,vpp,chemical,standard','2026-10-21 10:34:58','2026-10-21 10:34:58'),(30,'Ng